#!/usr/bin/env python3
"""Verify the byte counts and SHA-256 hashes in PACKAGE_MANIFEST.json."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
MANIFEST = ROOT / "PACKAGE_MANIFEST.json"


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
    expected = {item["path"]: item for item in manifest["files"]}
    actual = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and path != MANIFEST
        and "__pycache__" not in path.parts
        and not path.name.endswith((".pyc", ".pyo"))
    }

    assert actual == set(expected), "Package file list does not match the manifest"
    for relative, item in expected.items():
        path = ROOT / relative
        assert path.stat().st_size == item["bytes"], f"Byte count differs for {relative}"
        assert sha256(path) == item["sha256"], f"SHA-256 differs for {relative}"

    print(json.dumps({"status": "PASS", "files": len(expected)}, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Freeze label-free TAS evaluation inputs for independent provider API runs."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Any


FORBIDDEN = {
    "gold_label",
    "decisive_field",
    "mutation_family",
    "variant",
    "split",
    "numeric_result_if_released",
    "payload_hash",
    "metadata_hash",
    "contract_sha256",
}


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def inference_projection(task: dict[str, Any]) -> dict[str, Any]:
    return {
        "task_id": task["task_id"],
        "operation": task["operation"],
        "instruction": task["instruction"],
        "operands": [
            {
                "title": operand["title"],
                "period": operand["period"],
                "value": operand["value"],
                "metadata": operand["metadata"],
            }
            for operand in task["operands"]
        ],
    }


def find_forbidden(value: Any, path: str = "$") -> list[str]:
    found: list[str] = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = f"{path}.{key}"
            if key in FORBIDDEN:
                found.append(child_path)
            found.extend(find_forbidden(child, child_path))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            found.extend(find_forbidden(child, f"{path}[{index}]"))
    return found


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--benchmark", type=Path, required=True)
    parser.add_argument("--contract", type=Path, required=True)
    parser.add_argument("--outdir", type=Path, required=True)
    args = parser.parse_args()

    tasks = [
        json.loads(line)
        for line in args.benchmark.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    evaluation = [inference_projection(task) for task in tasks if task["split"] == "evaluation"]
    leaks = [location for task in evaluation for location in find_forbidden(task)]
    if leaks:
        raise RuntimeError(f"Scoring-only fields leaked into API inputs: {leaks[:10]}")
    if len(evaluation) != 160 or len({task["task_id"] for task in evaluation}) != 160:
        raise RuntimeError("Expected exactly 160 unique evaluation tasks")

    args.outdir.mkdir(parents=True, exist_ok=True)
    destination = args.outdir / "tas_api_eval_inputs_v5.jsonl"
    destination.write_text(
        "".join(json.dumps(task, ensure_ascii=True, separators=(",", ":")) + "\n" for task in evaluation),
        encoding="utf-8",
    )
    manifest = {
        "protocol": "TAS official-API v5 label-isolated input lock",
        "benchmark_path": str(args.benchmark),
        "benchmark_sha256": sha256(args.benchmark),
        "contract_path": str(args.contract),
        "contract_sha256": sha256(args.contract),
        "input_path": str(destination),
        "input_sha256": sha256(destination),
        "tasks": len(evaluation),
        "counterfactual_sets": 40,
        "requests_per_model_condition": len(evaluation),
        "scoring_fields_present": False,
        "forbidden_fields": sorted(FORBIDDEN),
        "isolation_boundary": (
            "The API runner consumes only this label-free file and sends one task per independent request. "
            "Gold labels and counterfactual-set membership are unavailable to inference code."
        ),
    }
    (args.outdir / "tas_api_input_manifest_v5.json").write_text(
        json.dumps(manifest, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Run a stateful, tool-using commit experiment for the TAS paper.

For every session the agent must read a valid measurement state through a
tool, stage a numerical claim, and then face an actual version transition in
an instrumented transactional sandbox.  At commit time the agent may reread
the current state or act from its staged state.  The same terminal release
request is executed against isolated policy branches, so policy comparisons
are paired within session rather than reconstructed from unrelated outputs.

The runner reads gold labels only inside the deterministic controller after
the model has produced its tool calls.  Gold labels and variant names are
never included in provider requests.
"""

from __future__ import annotations

import argparse
import concurrent.futures
import copy
import hashlib
import json
import math
import os
import statistics
import threading
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

import run_tas_official_apis_v5 as api
from tas_benchmark_v3 import table_oracle
from tas_runtime_v4 import digest, full_projection, payload_projection, scoped_projection


ROOT = Path(__file__).resolve().parents[1]
MODELS = {"sol": api.MODEL_SPECS["sol"], "claude": api.MODEL_SPECS["claude"]}
VARIANTS = ("valid", "plausible_conflict", "missing_obligation", "irrelevant_metadata")
POLICIES = (
    "stale_authorization",
    "payload_receipt",
    "full_state_fail_closed",
    "full_state_revalidate",
    "operation_scoped_revalidate",
    "always_revalidate",
)
WRITE_LOCK = threading.Lock()


SYSTEM = (
    "You are a statistical claim-release agent operating in a versioned environment. "
    "Use only the supplied tools. A staged numerical claim is not permission to release: "
    "metadata may change before commit. ACCEPT means all declared obligations are satisfied, "
    "REJECT means a known obligation is violated, and ABSTAIN means a load-bearing field is "
    "missing or an undefined denominator is zero. At the terminal step, RELEASE only when "
    "the currently authorized measurement state supports the staged operation. Apply SCAR-1.0: "
    "difference and ratio require equality of concept, unit, unit_multiplier, frequency, "
    "adjustment, price_basis, collection, and quantity_kind, plus equal periods; ratio also "
    "requires a nonzero denominator. Growth requires the same series at different periods, "
    "equality of those eight coordinates, and a nonzero initial value. Annual mean requires "
    "present and equal unit, unit_multiplier, frequency, collection, and quantity_kind, with "
    "frequency M, collection A, and quantity_kind rate. Ignore catalogue_language. Check "
    "coordinates in the listed order when more than one issue exists."
)


def now_utc() -> str:
    return datetime.now(timezone.utc).isoformat()


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def visible_task(task: dict[str, Any], transaction_task_id: str | None = None) -> dict[str, Any]:
    """Remove labels and benchmark bookkeeping before returning tool state."""
    keep = ("task_id", "operation", "instruction", "operands")
    result = {key: copy.deepcopy(task[key]) for key in keep}
    if transaction_task_id is not None:
        result["task_id"] = transaction_task_id
    return result


def tool_schema(name: str, provider: str) -> dict[str, Any]:
    descriptions = {
        "read_measurements": "Read the initial measurement state for the assigned operation.",
        "read_current_state": "Read the current measurement state after the environment version changed.",
        "stage_claim": "Stage or withhold a numerical claim based on the inspected initial state.",
        "commit_claim": "Request durable release or withhold the staged claim at the current version.",
    }
    if name in {"read_measurements", "read_current_state"}:
        parameters = {
            "type": "object",
            "properties": {"task_id": {"type": "string"}},
            "required": ["task_id"],
            "additionalProperties": False,
        }
    elif name == "stage_claim":
        parameters = {
            "type": "object",
            "properties": {
                "task_id": {"type": "string"},
                "operation": {"type": "string", "enum": ["difference", "ratio", "growth", "annual_mean"]},
                "action": {"type": "string", "enum": ["STAGE", "WITHHOLD"]},
                "claimed_value": {"anyOf": [{"type": "number"}, {"type": "null"}]},
                "rationale": {"type": "string"},
            },
            "required": ["task_id", "operation", "action", "claimed_value", "rationale"],
            "additionalProperties": False,
        }
    else:
        parameters = {
            "type": "object",
            "properties": {
                "task_id": {"type": "string"},
                "action": {"type": "string", "enum": ["RELEASE", "WITHHOLD"]},
                "claimed_value": {"anyOf": [{"type": "number"}, {"type": "null"}]},
                "rationale": {"type": "string"},
            },
            "required": ["task_id", "action", "claimed_value", "rationale"],
            "additionalProperties": False,
        }
    if provider == "openai":
        return {
            "type": "function",
            "name": name,
            "description": descriptions[name],
            "parameters": parameters,
            "strict": True,
        }
    return {
        "name": name,
        "description": descriptions[name],
        "input_schema": parameters,
    }


def extract_openai_call(response: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
    calls = [item for item in response.get("output", []) if item.get("type") == "function_call"]
    if len(calls) != 1:
        raise RuntimeError(f"Expected exactly one OpenAI function call, found {len(calls)}")
    call = calls[0]
    try:
        arguments = json.loads(call.get("arguments", "{}"))
    except json.JSONDecodeError as exc:
        raise RuntimeError("OpenAI function arguments were not valid JSON") from exc
    return str(call.get("name", "")), str(call.get("call_id", "")), arguments


def extract_anthropic_call(response: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
    calls = [block for block in response.get("content", []) if block.get("type") == "tool_use"]
    if len(calls) != 1:
        raise RuntimeError(f"Expected exactly one Anthropic tool call, found {len(calls)}")
    call = calls[0]
    arguments = call.get("input", {})
    if not isinstance(arguments, dict):
        raise RuntimeError("Anthropic tool input was not an object")
    return str(call.get("name", "")), str(call.get("id", "")), arguments


def usage_totals(responses: list[dict[str, Any]]) -> dict[str, int]:
    totals = {"input_tokens": 0, "output_tokens": 0, "reasoning_tokens": 0, "cache_read_tokens": 0}
    for response in responses:
        usage = response.get("usage", {}) or {}
        totals["input_tokens"] += int(usage.get("input_tokens", 0) or 0)
        totals["output_tokens"] += int(usage.get("output_tokens", 0) or 0)
        totals["cache_read_tokens"] += int(
            usage.get("cache_read_input_tokens", 0)
            or (usage.get("input_tokens_details", {}) or {}).get("cached_tokens", 0)
            or 0
        )
        totals["reasoning_tokens"] += int(
            (usage.get("output_tokens_details", {}) or {}).get("reasoning_tokens", 0) or 0
        )
    return totals


def openai_turn(
    input_items: list[dict[str, Any]],
    tool_names: list[str],
    forced_name: str | None,
    env: dict[str, str],
    max_attempts: int,
) -> tuple[dict[str, Any], float]:
    tools = [tool_schema(name, "openai") for name in tool_names]
    choice: Any = {"type": "function", "name": forced_name} if forced_name else "required"
    payload = {
        "model": MODELS["sol"][1],
        "instructions": SYSTEM,
        "input": input_items,
        "reasoning": {"effort": "medium"},
        "max_output_tokens": 2048,
        "tools": tools,
        "tool_choice": choice,
        "parallel_tool_calls": False,
        "include": ["reasoning.encrypted_content"],
        "store": False,
    }
    started = time.monotonic()
    response, _, status, _ = api.http_json(
        "https://api.openai.com/v1/responses",
        {"authorization": "Bearer " + env["OPEN_AI_API_KEY"]},
        payload,
        max_attempts,
    )
    if status != 200:
        raise RuntimeError(f"OpenAI status {status}")
    return response, (time.monotonic() - started) * 1000


def anthropic_turn(
    messages: list[dict[str, Any]],
    tool_names: list[str],
    forced_name: str | None,
    env: dict[str, str],
    max_attempts: int,
) -> tuple[dict[str, Any], float]:
    choice: dict[str, Any]
    if forced_name:
        choice = {"type": "tool", "name": forced_name, "disable_parallel_tool_use": True}
    else:
        choice = {"type": "any", "disable_parallel_tool_use": True}
    payload = {
        "model": MODELS["claude"][1],
        "max_tokens": 2048,
        "system": SYSTEM,
        "messages": messages,
        "tools": [tool_schema(name, "anthropic") for name in tool_names],
        "tool_choice": choice,
        "thinking": {"type": "adaptive"},
        "output_config": {"effort": "medium"},
    }
    headers = {"x-api-key": env["CLAUDE_API_KEY"], "anthropic-version": "2023-06-01"}
    workspace = env.get("CLAUDE_WORKSPACE_ID") or env.get("ANTHROPIC_WORKSPACE_ID")
    if workspace:
        headers["anthropic-workspace-id"] = workspace
    started = time.monotonic()
    response, _, status, _ = api.http_json(
        "https://api.anthropic.com/v1/messages", headers, payload, max_attempts
    )
    if status != 200:
        raise RuntimeError(f"Anthropic status {status}")
    return response, (time.monotonic() - started) * 1000


def finite_number(value: Any) -> bool:
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False


def relative_error(observed: Any, expected: Any) -> float:
    if not (finite_number(observed) and finite_number(expected)):
        return float("inf")
    a, b = float(observed), float(expected)
    return abs(a - b) / max(abs(b), 1e-12)


def effect_bound_match(committed: Any, staged: Any) -> bool:
    if not (finite_number(committed) and finite_number(staged)):
        return False
    return math.isclose(float(committed), float(staged), rel_tol=1e-12, abs_tol=1e-12)


def commit_boundary_message(change_notice: bool) -> str:
    if change_notice:
        return (
            "A provider synchronization event advanced the environment to state version 1. "
            "The staged claim is now at the commit boundary. You may call read_current_state "
            "before making exactly one terminal commit_claim call."
        )
    return (
        "The staged claim is now at the commit boundary. Use the available tools as needed, "
        "then make exactly one terminal commit_claim call."
    )


def execute_openai_session(
    valid: dict[str, Any],
    current: dict[str, Any],
    env: dict[str, str],
    max_attempts: int,
    change_notice: bool,
    freshness_channel: str,
) -> dict[str, Any]:
    task_id = valid["task_id"]
    transcript: list[dict[str, Any]] = []
    responses: list[dict[str, Any]] = []
    latencies: list[float] = []
    items: list[dict[str, Any]] = [{
        "role": "user",
        "content": (
            f"Task {task_id}: prepare the declared statistical operation. "
            "First call read_measurements for this task."
        ),
    }]

    response, latency = openai_turn(items, ["read_measurements"], "read_measurements", env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, args = extract_openai_call(response)
    transcript.append({"phase": "initial_read", "tool": name, "arguments": args})
    if name != "read_measurements" or args.get("task_id") != task_id:
        raise RuntimeError("Invalid initial read call")
    read_result = {"state_version": 0, "measurement_state": visible_task(valid, task_id)}
    items.extend(response.get("output", []))
    items.append({"type": "function_call_output", "call_id": call_id, "output": json.dumps(read_result)})

    response, latency = openai_turn(items, ["stage_claim"], "stage_claim", env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, stage_args = extract_openai_call(response)
    transcript.append({"phase": "stage", "tool": name, "arguments": stage_args})
    if name != "stage_claim":
        raise RuntimeError("Invalid stage tool")
    items.extend(response.get("output", []))
    stage_result = {"recorded": True, "stage_receipt": "version-0", "current_state_version": 0}
    items.append({"type": "function_call_output", "call_id": call_id, "output": json.dumps(stage_result)})
    if freshness_channel == "available":
        boundary_message = commit_boundary_message(change_notice)
        boundary_tools = ["read_current_state", "commit_claim"]
        forced_tool = None
    else:
        boundary_message = "The staged claim is now at the commit boundary. Make exactly one terminal commit_claim call."
        boundary_tools = ["commit_claim"]
        forced_tool = "commit_claim"
    items.append({"role": "user", "content": boundary_message})

    response, latency = openai_turn(items, boundary_tools, forced_tool, env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, args = extract_openai_call(response)
    reread = name == "read_current_state"
    transcript.append({"phase": "commit_entry", "tool": name, "arguments": args})
    if reread:
        if args.get("task_id") != task_id:
            raise RuntimeError("Invalid current-state read call")
        current_result = {"state_version": 1, "measurement_state": visible_task(current, task_id)}
        items.extend(response.get("output", []))
        items.append({"type": "function_call_output", "call_id": call_id, "output": json.dumps(current_result)})
        response, latency = openai_turn(items, ["commit_claim"], "commit_claim", env, max_attempts)
        responses.append(response); latencies.append(latency)
        name, call_id, commit_args = extract_openai_call(response)
        transcript.append({"phase": "terminal", "tool": name, "arguments": commit_args})
    else:
        commit_args = args
        transcript.append({"phase": "terminal", "tool": name, "arguments": commit_args})
    if name != "commit_claim":
        raise RuntimeError("Expected terminal commit_claim")
    return {
        "stage_args": stage_args,
        "commit_args": commit_args,
        "reread_current_state": reread,
        "transcript": transcript,
        "responses": responses,
        "latencies_ms": latencies,
    }


def anthropic_result_block(tool_use_id: str, value: dict[str, Any]) -> dict[str, Any]:
    return {"type": "tool_result", "tool_use_id": tool_use_id, "content": json.dumps(value)}


def execute_anthropic_session(
    valid: dict[str, Any],
    current: dict[str, Any],
    env: dict[str, str],
    max_attempts: int,
    change_notice: bool,
    freshness_channel: str,
) -> dict[str, Any]:
    task_id = valid["task_id"]
    transcript: list[dict[str, Any]] = []
    responses: list[dict[str, Any]] = []
    latencies: list[float] = []
    messages: list[dict[str, Any]] = [{
        "role": "user",
        "content": f"Task {task_id}: prepare the declared statistical operation. First call read_measurements for this task.",
    }]

    response, latency = anthropic_turn(messages, ["read_measurements"], "read_measurements", env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, args = extract_anthropic_call(response)
    transcript.append({"phase": "initial_read", "tool": name, "arguments": args})
    if name != "read_measurements" or args.get("task_id") != task_id:
        raise RuntimeError("Invalid initial read call")
    messages.append({"role": "assistant", "content": response.get("content", [])})
    messages.append({"role": "user", "content": [anthropic_result_block(call_id, {
        "state_version": 0, "measurement_state": visible_task(valid, task_id),
    })]})

    response, latency = anthropic_turn(messages, ["stage_claim"], "stage_claim", env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, stage_args = extract_anthropic_call(response)
    transcript.append({"phase": "stage", "tool": name, "arguments": stage_args})
    if name != "stage_claim":
        raise RuntimeError("Invalid stage tool")
    messages.append({"role": "assistant", "content": response.get("content", [])})
    boundary_message = (
        commit_boundary_message(change_notice)
        if freshness_channel == "available"
        else "The staged claim is now at the commit boundary. Make exactly one terminal commit_claim call."
    )
    messages.append({"role": "user", "content": [
        anthropic_result_block(call_id, {"recorded": True, "stage_receipt": "version-0", "current_state_version": 0}),
        {"type": "text", "text": boundary_message},
    ]})

    boundary_tools = ["read_current_state", "commit_claim"] if freshness_channel == "available" else ["commit_claim"]
    forced_tool = None if freshness_channel == "available" else "commit_claim"
    response, latency = anthropic_turn(messages, boundary_tools, forced_tool, env, max_attempts)
    responses.append(response); latencies.append(latency)
    name, call_id, args = extract_anthropic_call(response)
    reread = name == "read_current_state"
    transcript.append({"phase": "commit_entry", "tool": name, "arguments": args})
    if reread:
        if args.get("task_id") != task_id:
            raise RuntimeError("Invalid current-state read call")
        messages.append({"role": "assistant", "content": response.get("content", [])})
        messages.append({"role": "user", "content": [anthropic_result_block(call_id, {
            "state_version": 1, "measurement_state": visible_task(current, task_id),
        })]})
        response, latency = anthropic_turn(messages, ["commit_claim"], "commit_claim", env, max_attempts)
        responses.append(response); latencies.append(latency)
        name, call_id, commit_args = extract_anthropic_call(response)
        transcript.append({"phase": "terminal", "tool": name, "arguments": commit_args})
    else:
        commit_args = args
        transcript.append({"phase": "terminal", "tool": name, "arguments": commit_args})
    if name != "commit_claim":
        raise RuntimeError("Expected terminal commit_claim")
    return {
        "stage_args": stage_args,
        "commit_args": commit_args,
        "reread_current_state": reread,
        "transcript": transcript,
        "responses": responses,
        "latencies_ms": latencies,
    }


def policy_gate(
    policy: str,
    release_requested: bool,
    stage_accepted: bool,
    plan_payload: str,
    plan_full: str,
    plan_scoped: str,
    current_payload: str,
    current_full: str,
    current_scoped: str,
    oracle_decision: str,
) -> tuple[bool, bool, str]:
    if not stage_accepted:
        return False, False, "stage_rejected"
    if not release_requested:
        return False, False, "agent_withheld"
    if policy == "stale_authorization":
        return True, False, "cached_stage_authorization"
    if policy == "payload_receipt":
        return current_payload == plan_payload, False, "payload_equality"
    if policy == "full_state_fail_closed":
        return current_full == plan_full, False, "full_state_equality"
    if policy == "full_state_revalidate":
        changed = current_full != plan_full
        return (oracle_decision == "ACCEPT") if changed else True, changed, "full_state_revalidation" if changed else "full_state_match"
    if policy == "operation_scoped_revalidate":
        changed = current_scoped != plan_scoped
        return (oracle_decision == "ACCEPT") if changed else True, changed, "scoped_revalidation" if changed else "scoped_match"
    if policy == "always_revalidate":
        return oracle_decision == "ACCEPT", True, "always_revalidate"
    raise ValueError(policy)


def one_session(
    model_alias: str,
    replication: int,
    change_notice: bool,
    freshness_channel: str,
    valid: dict[str, Any],
    current: dict[str, Any],
    contract: dict[str, Any],
    contract_sha: str,
    env: dict[str, str],
    max_attempts: int,
) -> dict[str, Any]:
    started = now_utc()
    clock = time.monotonic()
    if model_alias == "sol":
        run = execute_openai_session(valid, current, env, max_attempts, change_notice, freshness_channel)
    else:
        run = execute_anthropic_session(valid, current, env, max_attempts, change_notice, freshness_channel)

    stage = run["stage_args"]
    commit = run["commit_args"]
    expected_value = valid["numeric_result_if_released"]
    stage_value_finite = finite_number(stage.get("claimed_value"))
    stage_relative_error = relative_error(stage.get("claimed_value"), expected_value)
    stage_value_within_0_1pct = stage_relative_error <= 0.001
    stage_value_within_1pct = stage_relative_error <= 0.01
    stage_value_type_ok = isinstance(stage.get("claimed_value"), (int, float)) and not isinstance(stage.get("claimed_value"), bool)
    stage_schema_ok = (
        stage.get("task_id") == valid["task_id"]
        and stage.get("operation") == valid["operation"]
        and stage.get("action") in {"STAGE", "WITHHOLD"}
        and ((stage.get("action") == "STAGE" and stage_value_type_ok) or (stage.get("action") == "WITHHOLD" and stage.get("claimed_value") is None))
    )
    stage_accepted = bool(stage_schema_ok and stage.get("action") == "STAGE" and stage_value_finite)
    commit_value_type_ok = isinstance(commit.get("claimed_value"), (int, float)) and not isinstance(commit.get("claimed_value"), bool)
    commit_schema_ok = (
        commit.get("task_id") == valid["task_id"]
        and commit.get("action") in {"RELEASE", "WITHHOLD"}
        and ((commit.get("action") == "RELEASE" and commit_value_type_ok) or (commit.get("action") == "WITHHOLD" and commit.get("claimed_value") is None))
    )
    commit_effect_bound = commit.get("action") == "WITHHOLD" or effect_bound_match(
        commit.get("claimed_value"), stage.get("claimed_value")
    )
    release_requested = bool(commit_schema_ok and commit_effect_bound and commit.get("action") == "RELEASE")

    oracle_decision, oracle_field = table_oracle(current, contract)
    invalid_state = oracle_decision != "ACCEPT"
    plan_payload = digest(payload_projection(valid))
    plan_full = digest(full_projection(valid, contract_sha))
    plan_scoped = digest(scoped_projection(valid, contract, contract_sha))
    current_payload = digest(payload_projection(current))
    current_full = digest(full_projection(current, contract_sha))
    current_scoped = digest(scoped_projection(current, contract, contract_sha))
    branch_rows = []
    for policy in POLICIES:
        released, revalidated, reason = policy_gate(
            policy, release_requested, stage_accepted,
            plan_payload, plan_full, plan_scoped,
            current_payload, current_full, current_scoped,
            oracle_decision,
        )
        branch_rows.append({
            "policy": policy,
            "released": released,
            "revalidated": revalidated,
            "unsafe_durable_release": bool(released and invalid_state),
            "valid_release_coverage": bool(released and not invalid_state),
            "false_invalidation": bool((not released) and not invalid_state and release_requested and stage_accepted),
            "correct_boundary": bool(released == (release_requested and stage_accepted and not invalid_state)),
            "gate_reason": reason,
        })

    provider, requested_model = MODELS[model_alias]
    response_ids = [str(response.get("id", "")) for response in run["responses"]]
    resolved_models = sorted({str(response.get("model", requested_model)) for response in run["responses"]})
    return {
        "session_id": f"{model_alias}-r{replication}-{valid['set_id']}",
        "model_alias": model_alias,
        "provider": provider,
        "requested_model": requested_model,
        "resolved_models": resolved_models,
        "replication": replication,
        "change_notice": bool(change_notice and freshness_channel == "available"),
        "balanced_assignment_notice": change_notice,
        "freshness_channel": freshness_channel,
        "set_id": valid["set_id"],
        "plan_task_id": valid["task_id"],
        "operation": valid["operation"],
        "transition_variant": current["variant"],
        "current_task_id": current["task_id"],
        "current_oracle_decision": oracle_decision,
        "current_oracle_field": oracle_field,
        "started_utc": started,
        "completed_utc": now_utc(),
        "elapsed_ms": round((time.monotonic() - clock) * 1000),
        "provider_latencies_ms": [round(value) for value in run["latencies_ms"]],
        "provider_request_ids": response_ids,
        "provider_turns": len(run["responses"]),
        "usage": usage_totals(run["responses"]),
        "stage": stage,
        "stage_schema_ok": stage_schema_ok,
        "stage_value_finite": stage_value_finite,
        "stage_relative_error": stage_relative_error,
        "stage_value_within_0_1pct": stage_value_within_0_1pct,
        "stage_value_within_1pct": stage_value_within_1pct,
        "stage_accepted": stage_accepted,
        "reread_current_state": run["reread_current_state"],
        "commit": commit,
        "commit_schema_ok": commit_schema_ok,
        "commit_effect_bound": commit_effect_bound,
        "release_requested": release_requested,
        "direct_stale_release_request": bool(release_requested and not run["reread_current_state"]),
        "self_withheld_invalid": bool(invalid_state and commit.get("action") == "WITHHOLD"),
        "transcript": run["transcript"],
        "receipt_digests": {
            "plan_payload": plan_payload, "plan_full": plan_full, "plan_scoped": plan_scoped,
            "current_payload": current_payload, "current_full": current_full, "current_scoped": current_scoped,
        },
        "policy_branches": branch_rows,
    }


def read_completed(path: Path) -> dict[str, dict[str, Any]]:
    if not path.exists():
        return {}
    result = {}
    for raw in path.read_text(encoding="utf-8").splitlines():
        if raw.strip():
            row = json.loads(raw)
            result[row["session_id"]] = row
    return result


def append_jsonl(path: Path, row: dict[str, Any]) -> None:
    with WRITE_LOCK, path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(row, ensure_ascii=True, separators=(",", ":")) + "\n")
        stream.flush()


def assign_sessions(by_set: dict[str, dict[str, dict[str, Any]]], models: list[str], replications: list[int]) -> list[tuple[str, int, bool, dict[str, Any], dict[str, Any]]]:
    set_ids = sorted(by_set)
    if len(set_ids) % len(VARIANTS):
        raise RuntimeError("Latin assignment requires set count divisible by four")
    sessions = []
    for model_index, model in enumerate(models):
        for replication in replications:
            counts = {variant: 0 for variant in VARIANTS}
            notice_counts = {(variant, notice): 0 for variant in VARIANTS for notice in (False, True)}
            for index, set_id in enumerate(set_ids):
                variant = VARIANTS[(index + replication - 1 + 2 * model_index) % len(VARIANTS)]
                change_notice = ((index // 4) + replication + model_index) % 2 == 0
                counts[variant] += 1
                notice_counts[(variant, change_notice)] += 1
                sessions.append((model, replication, change_notice, by_set[set_id]["valid"], by_set[set_id][variant]))
            if len(set(counts.values())) != 1:
                raise RuntimeError(f"Unbalanced transition assignment: {model}/r{replication}: {counts}")
            if len(set(notice_counts.values())) != 1:
                raise RuntimeError(f"Unbalanced notice assignment: {model}/r{replication}: {notice_counts}")
    return sessions


def bootstrap_ci(frame: pd.DataFrame, column: str, reps: int = 10000) -> list[float]:
    by_set = frame.groupby("set_id")[column].mean()
    rng = np.random.default_rng(20260901)
    values = by_set.to_numpy(dtype=float)
    selections = rng.integers(0, len(values), size=(reps, len(values)))
    sampled = values[selections].mean(axis=1)
    return [float(np.quantile(sampled, 0.025)), float(np.quantile(sampled, 0.975))]


def summarize(records: list[dict[str, Any]], outdir: Path) -> dict[str, Any]:
    session_rows = []
    branch_rows = []
    durable_rows = []
    for row in records:
        usage = row["usage"]
        base = {
            "session_id": row["session_id"], "model": row["model_alias"],
            "replication": row["replication"], "set_id": row["set_id"],
            "change_notice": row["change_notice"],
            "freshness_channel": row.get("freshness_channel", "available"),
            "operation": row["operation"], "variant": row["transition_variant"],
            "oracle_decision": row["current_oracle_decision"],
            "stage_accepted": row["stage_accepted"],
            "stage_value_finite": row["stage_value_finite"],
            "stage_relative_error": row["stage_relative_error"],
            "stage_value_within_0_1pct": row["stage_value_within_0_1pct"],
            "stage_value_within_1pct": row["stage_value_within_1pct"],
            "commit_effect_bound": row["commit_effect_bound"],
            "reread": row["reread_current_state"], "release_requested": row["release_requested"],
            "direct_stale_release_request": row["direct_stale_release_request"],
            "self_withheld_invalid": row["self_withheld_invalid"],
            "provider_turns": row["provider_turns"], "elapsed_ms": row["elapsed_ms"],
            "input_tokens": usage["input_tokens"], "output_tokens": usage["output_tokens"],
            "reasoning_tokens": usage["reasoning_tokens"],
        }
        session_rows.append(base)
        for branch in row["policy_branches"]:
            branch_rows.append({**base, **branch})
            if branch["released"]:
                durable_rows.append({
                    "session_id": row["session_id"], "policy": branch["policy"],
                    "set_id": row["set_id"], "variant": row["transition_variant"],
                    "operation": row["operation"], "state_version": 1,
                    "oracle_decision": row["current_oracle_decision"],
                    "unsafe": branch["unsafe_durable_release"],
                    "commit_value": row["commit"].get("claimed_value"),
                    "committed_utc": row["completed_utc"],
                })
    sessions = pd.DataFrame(session_rows)
    branches = pd.DataFrame(branch_rows)
    sessions.to_csv(outdir / "tas_live_sessions_v6.csv", index=False)
    branches.to_csv(outdir / "tas_live_policy_branches_v6.csv", index=False)
    (outdir / "tas_durable_commits_v6.jsonl").write_text(
        "".join(json.dumps(row, separators=(",", ":")) + "\n" for row in durable_rows), encoding="utf-8"
    )

    session_summary = []
    for model, group in sessions.groupby("model"):
        invalid = group[~group.oracle_decision.eq("ACCEPT")]
        session_summary.append({
            "model": model,
            "sessions": len(group),
            "stage_acceptance": float(group.stage_accepted.mean()),
            "finite_stage_value_rate": float(group.stage_value_finite.mean()),
            "stage_value_within_0_1pct": float(group.stage_value_within_0_1pct.mean()),
            "stage_value_within_1pct": float(group.stage_value_within_1pct.mean()),
            "median_stage_relative_error": float(group.stage_relative_error.median()),
            "commit_effect_binding_rate": float(group.commit_effect_bound.mean()),
            "reread_rate": float(group.reread.mean()),
            "direct_stale_release_request_rate": float(group.direct_stale_release_request.mean()),
            "self_withhold_given_invalid": float(invalid.self_withheld_invalid.mean()),
            "median_provider_turns": float(group.provider_turns.median()),
            "median_elapsed_ms": float(group.elapsed_ms.median()),
            "median_total_tokens": float((group.input_tokens + group.output_tokens).median()),
        })

    policy_summary = []
    for policy, group in branches.groupby("policy"):
        invalid = group[~group.oracle_decision.eq("ACCEPT")]
        valid = group[group.oracle_decision.eq("ACCEPT")]
        release_attempts = group[group.release_requested & group.stage_accepted]
        policy_summary.append({
            "policy": policy,
            "sessions": len(group),
            "unsafe_release_given_invalid": float(invalid.unsafe_durable_release.mean()),
            "unsafe_ci95_set_clustered": bootstrap_ci(invalid, "unsafe_durable_release"),
            "valid_release_coverage": float(valid.released.mean()),
            "coverage_ci95_set_clustered": bootstrap_ci(valid, "released"),
            "false_invalidation_given_valid_attempt": float(
                valid[valid.release_requested & valid.stage_accepted].false_invalidation.mean()
            ) if bool((valid.release_requested & valid.stage_accepted).any()) else float("nan"),
            "revalidation_given_release_attempt": float(release_attempts.revalidated.mean()) if len(release_attempts) else float("nan"),
            "boundary_accuracy": float(group.correct_boundary.mean()),
            "durable_releases": int(group.released.sum()),
        })

    per_variant = branches.groupby(["policy", "variant"]).agg(
        sessions=("session_id", "size"),
        release_rate=("released", "mean"),
        unsafe_rate=("unsafe_durable_release", "mean"),
        revalidation_rate=("revalidated", "mean"),
    ).reset_index()
    per_variant.to_csv(outdir / "tas_live_policy_by_variant_v6.csv", index=False)
    pd.DataFrame(session_summary).to_csv(outdir / "tas_live_model_summary_v6.csv", index=False)
    pd.DataFrame(policy_summary).to_csv(outdir / "tas_live_policy_summary_v6.csv", index=False)
    behavior_by_notice = sessions.groupby(["model", "change_notice"]).agg(
        sessions=("session_id", "size"),
        reread_rate=("reread", "mean"),
        release_request_rate=("release_requested", "mean"),
        direct_stale_release_request_rate=("direct_stale_release_request", "mean"),
        stage_acceptance=("stage_accepted", "mean"),
        commit_effect_binding=("commit_effect_bound", "mean"),
    ).reset_index()
    behavior_by_notice.to_csv(outdir / "tas_live_behavior_by_notice_v6.csv", index=False)

    summary = {
        "protocol": "Stateful official-API tool-use commit experiment in a versioned transactional sandbox",
        "sessions": len(sessions),
        "models": sorted(sessions.model.unique().tolist()),
        "replications": sorted(int(x) for x in sessions.replication.unique()),
        "transition_counts": sessions.variant.value_counts().sort_index().to_dict(),
        "change_notice_counts": sessions.change_notice.value_counts().sort_index().to_dict(),
        "freshness_channel_counts": sessions.freshness_channel.value_counts().sort_index().to_dict(),
        "operations": sessions.operation.value_counts().sort_index().to_dict(),
        "all_stage_tool_schemas_valid": bool(all(row["stage_schema_ok"] for row in records)),
        "all_commit_tool_schemas_valid": bool(all(row["commit_schema_ok"] for row in records)),
        "unique_provider_request_ids": len({rid for row in records for rid in row["provider_request_ids"] if rid}),
        "provider_turns": int(sessions.provider_turns.sum()),
        "session_summary": session_summary,
        "policy_summary": policy_summary,
        "boundary": (
            "The experiment observes live model tool use and an actual controlled state transition. "
            "It does not observe uncontrolled provider-data drift or deployment traffic."
        ),
    }
    (outdir / "tas_live_summary_v6.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    return summary


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--env", type=Path, default=ROOT / ".env")
    parser.add_argument("--benchmark", type=Path, required=True)
    parser.add_argument("--contract", type=Path, required=True)
    parser.add_argument("--outdir", type=Path, required=True)
    parser.add_argument("--models", nargs="+", choices=sorted(MODELS), default=sorted(MODELS))
    parser.add_argument("--replications", nargs="+", type=int, default=[1, 2, 3])
    parser.add_argument("--concurrency", type=int, default=6)
    parser.add_argument("--max-attempts", type=int, default=5)
    parser.add_argument("--limit", type=int, default=0, help="Smoke-test first N assigned sessions")
    parser.add_argument("--freshness-channel", choices=("available", "unavailable"), default="available")
    args = parser.parse_args()
    args.outdir.mkdir(parents=True, exist_ok=True)

    env = api.load_env(args.env)
    for key in ("CLAUDE_WORKSPACE_ID", "ANTHROPIC_WORKSPACE_ID"):
        if os.environ.get(key):
            env[key] = os.environ[key]
    required = {"OPEN_AI_API_KEY" if MODELS[model][0] == "openai" else "CLAUDE_API_KEY" for model in args.models}
    missing = sorted(key for key in required if not env.get(key))
    if missing:
        raise RuntimeError(f"Missing keys: {missing}")

    tasks = [json.loads(line) for line in args.benchmark.read_text(encoding="utf-8").splitlines() if line.strip()]
    evaluation = [task for task in tasks if task["split"] == "evaluation"]
    by_set: dict[str, dict[str, dict[str, Any]]] = {}
    for task in evaluation:
        by_set.setdefault(task["set_id"], {})[task["variant"]] = task
    if len(by_set) != 40 or any(set(variants) != set(VARIANTS) for variants in by_set.values()):
        raise RuntimeError("Expected 40 complete evaluation counterfactual sets")
    contract = json.loads(args.contract.read_text(encoding="utf-8"))
    contract_sha = sha256_bytes(args.contract.read_bytes())
    assignments = assign_sessions(by_set, args.models, sorted(set(args.replications)))
    if args.limit:
        assignments = assignments[:args.limit]

    records_path = args.outdir / "tas_live_records_v6.jsonl"
    existing = read_completed(records_path)
    pending = [item for item in assignments if f"{item[0]}-r{item[1]}-{item[3]['set_id']}" not in existing]
    print(json.dumps({"assigned": len(assignments), "completed": len(existing), "pending": len(pending)}), flush=True)
    failures: list[dict[str, str]] = []
    if pending:
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.concurrency) as pool:
            futures = {
                pool.submit(one_session, model, replication, change_notice, args.freshness_channel, valid, current, contract, contract_sha, env, args.max_attempts):
                (model, replication, valid["set_id"])
                for model, replication, change_notice, valid, current in pending
            }
            done = 0
            for future in concurrent.futures.as_completed(futures):
                key = futures[future]
                try:
                    append_jsonl(records_path, future.result())
                except Exception as exc:
                    failures.append({"session": "-".join(map(str, key)), "error": str(exc)[:1000]})
                done += 1
                if done % 10 == 0 or done == len(pending):
                    print(json.dumps({"finished_now": done, "pending_total": len(pending), "failures": len(failures)}), flush=True)

    completed = read_completed(records_path)
    ordered_ids = [f"{m}-r{r}-{v['set_id']}" for m, r, _, v, _ in assignments]
    records = [completed[key] for key in ordered_ids if key in completed]
    if failures or len(records) != len(assignments):
        (args.outdir / "tas_live_failures_v6.json").write_text(json.dumps(failures, indent=2) + "\n", encoding="utf-8")
        raise RuntimeError(f"Incomplete live run: records={len(records)}, expected={len(assignments)}, failures={len(failures)}. Rerun to resume.")

    summary = summarize(records, args.outdir)
    manifest = {
        "created_utc": now_utc(),
        "benchmark_path": str(args.benchmark),
        "benchmark_sha256": sha256_bytes(args.benchmark.read_bytes()),
        "contract_path": str(args.contract),
        "contract_sha256": contract_sha,
        "models": [MODELS[m][1] for m in args.models],
        "replications": sorted(set(args.replications)),
        "freshness_channel": args.freshness_channel,
        "sessions": len(records),
        "transition_assignment": "balanced Latin rotation over locked set order, replication, model, and change-notice factor",
        "provider_storage_requested": "false for OpenAI; provider default for Anthropic",
        "gold_visible_to_models": False,
        "summary_sha256": sha256_bytes((args.outdir / "tas_live_summary_v6.json").read_bytes()),
    }
    (args.outdir / "tas_live_manifest_v6.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(summary, indent=2), flush=True)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Build a realistic, locked-split semantic-counterfactual TAS benchmark."""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import math
import random
from collections import Counter
from pathlib import Path
from typing import Any

import pandas as pd

from tas_benchmark import bis_points, ecb_points, eurostat_points
from tas_semantic_counterfactual import (
    build_seeds,
    normalize_point,
    task_result,
    world_bank_points,
)


DEV_FIELDS = ["concept", "unit_multiplier", "frequency", "adjustment"]
EVAL_FIELDS = ["unit", "price_basis", "collection", "quantity_kind"]


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def payload_hash(operation: str, operands: list[dict[str, Any]]) -> str:
    payload = {"operation": operation, "values": [[o["period"], o["value"]] for o in operands]}
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


def metadata_hash(operands: list[dict[str, Any]]) -> str:
    return hashlib.sha256(json.dumps([o["metadata"] for o in operands], sort_keys=True).encode()).hexdigest()


def plausible_alternative(field: str, original: str, operation: str) -> str:
    pools = {
        "concept": ["gross national income at market prices", "consumer price index", "industrial production index", "reference exchange rate"],
        "unit": ["EUR", "USD", "JPY", "CP_MEUR", "CLV15_MEUR", "index 2015=100"],
        "unit_multiplier": ["0", "3", "6"],
        "frequency": ["A", "Q", "M"],
        "adjustment": ["NA", "seasonally adjusted", "not seasonally adjusted"],
        "price_basis": ["NA", "current prices", "constant 2015 prices", "chain linked volumes, 2015"],
        "collection": ["A", "E", "sum of period flows", "average of observations through period", "end of period"],
        "quantity_kind": ["flow", "stock", "rate", "index"],
    }
    for candidate in pools[field]:
        if candidate != str(original):
            if operation == "annual_mean" and field == "collection" and candidate == "A":
                continue
            return candidate
    raise ValueError(f"No alternative for {field}={original}")


def assign_mutations(seeds: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_operation: dict[str, list[dict[str, Any]]] = {}
    for seed in seeds:
        by_operation.setdefault(seed["operation"], []).append(copy.deepcopy(seed))
    assigned = []
    for operation in ["difference", "ratio", "growth", "annual_mean"]:
        group = by_operation[operation]
        if len(group) != 20:
            raise RuntimeError(f"Expected 20 {operation} seeds")
        for j, seed in enumerate(group):
            split = "development" if j < 10 else "evaluation"
            pool = DEV_FIELDS if split == "development" else EVAL_FIELDS
            if operation == "annual_mean":
                pool = ["frequency", "unit_multiplier"] if split == "development" else ["unit", "collection", "quantity_kind"]
            seed["split"] = split
            seed["mutation"] = pool[j % len(pool)]
            assigned.append(seed)
    return assigned


def make_tasks(seeds: list[dict[str, Any]], contract_sha: str) -> list[dict[str, Any]]:
    tasks = []
    for set_no, seed in enumerate(seeds, 1):
        base = copy.deepcopy(seed["operands"])
        field = seed["mutation"]
        if seed["operation"] == "annual_mean" and field in {"frequency", "collection", "quantity_kind"}:
            conflict_target = list(range(len(base)))
        elif seed["operation"] == "annual_mean":
            conflict_target = [0]
        else:
            conflict_target = [1]
        missing_target = list(range(len(base))) if seed["operation"] == "annual_mean" else [1]
        variants: list[tuple[str, str, list[dict[str, Any]], str]] = []
        variants.append(("valid", "ACCEPT", copy.deepcopy(base), "none"))
        conflict = copy.deepcopy(base)
        for idx in conflict_target:
            original = str(conflict[idx]["metadata"].get(field, ""))
            conflict[idx]["metadata"][field] = plausible_alternative(field, original, seed["operation"])
        variants.append(("plausible_conflict", "REJECT", conflict, field))
        missing = copy.deepcopy(base)
        for idx in missing_target:
            missing[idx]["metadata"][field] = None
        variants.append(("missing_obligation", "ABSTAIN", missing, field))
        irrelevant = copy.deepcopy(base)
        for operand in irrelevant:
            operand["metadata"]["catalogue_language"] = "English"
        variants.append(("irrelevant_metadata", "ACCEPT", irrelevant, "none"))
        prefix = "D" if seed["split"] == "development" else "E"
        set_id = f"{prefix}{set_no:03d}"
        for variant_no, (variant, label, operands, decisive) in enumerate(variants, 1):
            tasks.append({
                "task_id": f"{set_id}V{variant_no}",
                "set_id": set_id,
                "split": seed["split"],
                "variant": variant,
                "operation": seed["operation"],
                "instruction": {
                    "difference": "report A minus B",
                    "ratio": "report A divided by B",
                    "growth": "report percent change from A to B",
                    "annual_mean": "report the arithmetic mean of the declared monthly-average rate observations",
                }[seed["operation"]],
                "operands": operands,
                "mutation_family": field,
                "gold_label": label,
                "decisive_field": decisive,
                "numeric_result_if_released": task_result(seed["operation"], operands),
                "payload_hash": payload_hash(seed["operation"], operands),
                "metadata_hash": metadata_hash(operands),
                "contract_sha256": contract_sha,
            })
    random.Random(20260901).shuffle(tasks)
    return tasks


def table_oracle(task: dict[str, Any], contract: dict[str, Any]) -> tuple[str, str]:
    operation = task["operation"]
    operands = task["operands"]
    rule = contract["operations"][operation]
    for field in rule.get("required_present", []):
        values = [x["metadata"].get(field) for x in operands]
        if any(v is None or v == "" for v in values):
            return "ABSTAIN", field
    for field in rule.get("required_equal", []):
        values = [x["metadata"].get(field) for x in operands]
        if any(v is None or v == "" for v in values):
            return "ABSTAIN", field
        if len(set(map(str, values))) != 1:
            return "REJECT", field
    for field, required in rule.get("required_values", {}).items():
        if any(str(x["metadata"].get(field)) != str(required) for x in operands):
            return "REJECT", field
    if rule.get("period_relation") == "equal" and len({x["period"] for x in operands}) != 1:
        return "REJECT", "period"
    if rule.get("period_relation") == "different" and len({x["period"] for x in operands}) == 1:
        return "REJECT", "period"
    if rule.get("same_series") and len({x["series_id"] for x in operands}) != 1:
        return "REJECT", "series_id"
    nonzero = rule.get("nonzero_operand")
    if nonzero is not None and float(operands[int(nonzero)]["value"]) == 0:
        return "ABSTAIN", "zero_denominator"
    return "ACCEPT", "none"


def reference_oracle(task: dict[str, Any]) -> tuple[str, str]:
    op, operands = task["operation"], task["operands"]
    if op == "annual_mean":
        fields = ["unit", "unit_multiplier", "frequency", "collection", "quantity_kind"]
        for field in fields:
            values = [x["metadata"].get(field) for x in operands]
            if any(v is None or v == "" for v in values):
                return "ABSTAIN", field
            if len(set(map(str, values))) != 1:
                return "REJECT", field
        for field, required in [("frequency", "M"), ("collection", "A"), ("quantity_kind", "rate")]:
            if str(operands[0]["metadata"].get(field)) != required:
                return "REJECT", field
        return "ACCEPT", "none"
    fields = ["concept", "unit", "unit_multiplier", "frequency", "adjustment", "price_basis", "collection", "quantity_kind"]
    for field in fields:
        a, b = operands[0]["metadata"].get(field), operands[1]["metadata"].get(field)
        if a is None or b is None or a == "" or b == "":
            return "ABSTAIN", field
        if str(a) != str(b):
            return "REJECT", field
    if op in {"difference", "ratio"} and operands[0]["period"] != operands[1]["period"]:
        return "REJECT", "period"
    if op == "growth" and (operands[0]["series_id"] != operands[1]["series_id"] or operands[0]["period"] == operands[1]["period"]):
        return "REJECT", "series_id"
    if op == "ratio" and float(operands[1]["value"]) == 0:
        return "ABSTAIN", "zero_denominator"
    if op == "growth" and float(operands[0]["value"]) == 0:
        return "ABSTAIN", "zero_denominator"
    return "ACCEPT", "none"


def prompt_item(task: dict[str, Any], condition: str) -> dict[str, Any]:
    item = {
        "task_id": task["task_id"], "operation": task["operation"], "instruction": task["instruction"],
        "operands": [{"title": x["title"], "period": x["period"], "value": x["value"]} for x in task["operands"]],
    }
    if condition != "payload_only":
        for dst, src in zip(item["operands"], task["operands"]):
            dst["metadata"] = src["metadata"]
    return item


def write_prompts(tasks: list[dict[str, Any]], contract: dict[str, Any], outdir: Path) -> None:
    evaluation = [x for x in tasks if x["split"] == "evaluation"]
    by_operation: dict[str, list[str]] = {}
    for task in evaluation:
        by_operation.setdefault(task["operation"], []).append(task["set_id"])
    batches: list[set[str]] = []
    for operation in ["difference", "ratio", "growth"]:
        batches.append(set(sorted(set(by_operation[operation]))))
    annual = sorted(set(by_operation["annual_mean"]))
    batches.extend([set(annual[:5]), set(annual[5:])])
    contract_text = json.dumps(contract["operations"], sort_keys=True)
    lead = (
        "You are a statistical claim-release agent. For every task output exactly one compact JSON object per line with "
        "task_id, decision (ACCEPT, REJECT, or ABSTAIN), and decisive_field. ACCEPT a measurement-admissible claim, "
        "REJECT a known violation, and ABSTAIN when a load-bearing field is missing. Do not use tools and do not add prose.\n"
    )
    prompt_dir = outdir / "prompts"
    prompt_dir.mkdir(exist_ok=True)
    for condition in ["payload_only", "metadata", "contract"]:
        condition_lead = lead
        if condition == "contract":
            condition_lead += (
                f"Apply this exact locked operation contract: {contract_text}. Ignore catalogue_language. "
                "Check required fields in the listed order.\n"
            )
        for batch_no, batch_sets in enumerate(batches, 1):
            items = [prompt_item(x, condition) for x in evaluation if x["set_id"] in batch_sets]
            (prompt_dir / f"{condition}_batch{batch_no}.txt").write_text(
                condition_lead + json.dumps(items, ensure_ascii=True), encoding="utf-8"
            )
    gold_fields = ["task_id", "set_id", "split", "variant", "operation", "mutation_family", "gold_label", "decisive_field"]
    (outdir / "tas_eval_gold_v3.jsonl").write_text(
        "".join(json.dumps({k: x[k] for k in gold_fields}) + "\n" for x in evaluation), encoding="utf-8"
    )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", type=Path, required=True)
    parser.add_argument("--contract", type=Path, required=True)
    args = parser.parse_args()
    args.outdir.mkdir(parents=True, exist_ok=True)
    raw = args.outdir / "raw"
    contract = json.loads(args.contract.read_text())
    contract_sha = sha(args.contract)
    source = eurostat_points(raw) + ecb_points(raw) + bis_points(raw) + world_bank_points(raw)
    seeds = assign_mutations(build_seeds([normalize_point(x) for x in source]))
    tasks = make_tasks(seeds, contract_sha)
    oracle_rows = []
    for task in tasks:
        a, field_a = table_oracle(task, contract)
        b, field_b = reference_oracle(task)
        oracle_rows.append({
            "task_id": task["task_id"], "gold": task["gold_label"], "table": a, "reference": b,
            "expected_field": task["decisive_field"], "table_field": field_a, "reference_field": field_b,
            "oracles_agree": a == b and field_a == field_b,
            "gold_agrees": a == b == task["gold_label"],
        })
    oracle = pd.DataFrame(oracle_rows)
    if not oracle.oracles_agree.all() or not oracle.gold_agrees.all():
        print(oracle[~(oracle.oracles_agree & oracle.gold_agrees)].head(20).to_string(index=False))
        raise RuntimeError("Oracle disagreement")
    by_set: dict[str, list[dict[str, Any]]] = {}
    for task in tasks:
        by_set.setdefault(task["set_id"], []).append(task)
    for set_id, members in by_set.items():
        if len({x["payload_hash"] for x in members}) != 1:
            raise RuntimeError(f"Payload invariance failed: {set_id}")
        if sorted(x["gold_label"] for x in members) != ["ABSTAIN", "ACCEPT", "ACCEPT", "REJECT"]:
            raise RuntimeError(f"Label structure failed: {set_id}")
    with (args.outdir / "tas_benchmark_v3.jsonl").open("w") as stream:
        for task in tasks:
            stream.write(json.dumps(task, ensure_ascii=True) + "\n")
    oracle.to_csv(args.outdir / "tas_oracle_agreement_v3.csv", index=False)
    write_prompts(tasks, contract, args.outdir)
    split_counts = pd.crosstab(pd.Series([x["split"] for x in tasks]), pd.Series([x["operation"] for x in tasks]))
    mutation_counts = pd.crosstab(pd.Series([x["split"] for x in tasks]), pd.Series([x["mutation_family"] for x in tasks]))
    summary = {
        "contract_id": contract["contract_id"], "contract_sha256": contract_sha,
        "source_observations": len(source), "sets": len(by_set), "tasks": len(tasks),
        "development_sets": sum(x["split"] == "development" for x in seeds),
        "evaluation_sets": sum(x["split"] == "evaluation" for x in seeds),
        "evaluation_tasks": sum(x["split"] == "evaluation" for x in tasks),
        "split_operation_counts": split_counts.to_dict(),
        "split_mutation_counts": mutation_counts.to_dict(),
        "realistic_mutations": True,
        "sentinel_strings_present": any("COUNTERFACTUAL" in json.dumps(x) for x in tasks),
        "payload_invariant_sets": sum(len({x["payload_hash"] for x in m}) == 1 for m in by_set.values()),
        "dual_oracle_agreement": int(oracle.oracles_agree.sum()),
        "dual_oracle_gold_agreement": int(oracle.gold_agrees.sum()),
        "circularity_boundary": "Dual-oracle agreement is an implementation invariant under the locked contract, not external scientific validation.",
    }
    (args.outdir / "tas_benchmark_v3_summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Build Same Numbers, Different Claim: a semantic-counterfactual benchmark.

Each four-member set fixes the operation and every numeric payload while
varying only measurement metadata.  The variants are ACCEPT (valid), REJECT
(known semantic conflict), ABSTAIN (load-bearing metadata removed), and an
irrelevant-metadata ACCEPT control.  A separate exact-scale suite tests safe
repair.  All source observations come from public Eurostat, ECB, BIS, or World
Bank endpoints and are cached with their source URLs.
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import math
import random
import urllib.parse
import urllib.request
from collections import Counter
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import pandas as pd

from tas_benchmark import SeriesPoint, bis_points, ecb_points, eurostat_points


WORLD_BANK = "https://api.worldbank.org/v2/country"
REQUIRED_PAIR = [
    "concept", "unit", "unit_multiplier", "frequency", "adjustment",
    "price_basis", "collection", "quantity_kind",
]


@dataclass(frozen=True)
class WBPoint:
    provider: str
    series_id: str
    title: str
    period: str
    value: float
    concept: str
    unit: str
    unit_label: str
    unit_multiplier: str
    frequency: str
    adjustment: str
    price_basis: str
    collection: str
    geography: str
    source_url: str


def cached_json(url: str, raw_dir: Path) -> Any:
    raw_dir.mkdir(parents=True, exist_ok=True)
    path = raw_dir / f"wb_{hashlib.sha256(url.encode()).hexdigest()[:20]}.json"
    if path.exists():
        return json.loads(path.read_text(encoding="utf-8"))
    req = urllib.request.Request(url, headers={"User-Agent": "AAAI-TAS-semantic-counterfactual/1.0"})
    with urllib.request.urlopen(req, timeout=60) as response:
        body = response.read()
    path.write_bytes(body)
    return json.loads(body)


def world_bank_points(raw_dir: Path) -> list[WBPoint]:
    countries = "DEU;FRA;ITA;ESP;NLD"
    indicators = {
        "NY.GDP.MKTP.CD": ("GDP at market prices", "USD", "current prices"),
        "NY.GDP.MKTP.KD": ("GDP at market prices", "USD", "constant 2015 prices"),
    }
    points: list[WBPoint] = []
    for indicator, (concept, unit, price_basis) in indicators.items():
        url = f"{WORLD_BANK}/{countries}/indicator/{indicator}?" + urllib.parse.urlencode(
            {"date": "2022:2024", "format": "json", "per_page": 100}
        )
        payload = cached_json(url, raw_dir)
        for row in payload[1]:
            if row.get("value") is None:
                continue
            points.append(WBPoint(
                provider="World Bank", series_id=f"{indicator}.{row['countryiso3code']}",
                title=f"{row['indicator']['value']} - {row['country']['value']}",
                period=row["date"], value=float(row["value"]), concept=concept,
                unit=unit, unit_label="current US dollars" if price_basis == "current prices" else "constant 2015 US dollars",
                unit_multiplier="0", frequency="A", adjustment="NA", price_basis=price_basis,
                collection="sum of period flows", geography=row["countryiso3code"], source_url=url,
            ))
    return points


def normalize_point(point: SeriesPoint | WBPoint) -> dict[str, Any]:
    p = asdict(point)
    multiplier = p["unit_multiplier"]
    if multiplier in {"encoded in unit", ""}:
        multiplier = "0"
    concept = p["concept"]
    quantity_kind = "flow" if "GDP" in concept else "rate"
    p["metadata"] = {
        "concept": concept, "unit": p["unit"], "unit_multiplier": str(multiplier),
        "frequency": p["frequency"], "adjustment": p["adjustment"],
        "price_basis": p["price_basis"], "collection": p["collection"],
        "quantity_kind": quantity_kind, "geography": p["geography"],
    }
    return {k: p[k] for k in ["provider", "series_id", "title", "period", "value", "source_url"]} | {
        "metadata": p["metadata"]
    }


def lookup(points: list[dict[str, Any]]) -> dict[tuple[str, str, str], dict[str, Any]]:
    return {(p["provider"], p["series_id"], p["period"]): p for p in points}


def pair_seed(operation: str, a: dict[str, Any], b: dict[str, Any], mutation: str) -> dict[str, Any]:
    if operation in {"difference", "ratio"} and a["period"] != b["period"]:
        raise ValueError("Cross-sectional operations require a common period")
    if operation == "growth" and (a["series_id"] != b["series_id"] or a["period"] == b["period"]):
        raise ValueError("Growth requires one series at two distinct periods")
    return {"operation": operation, "operands": [copy.deepcopy(a), copy.deepcopy(b)], "mutation": mutation}


def annual_seed(points: list[dict[str, Any]], provider: str, series_id: str, periods: list[str]) -> dict[str, Any]:
    selected = [p for p in points if p["provider"] == provider and p["series_id"] == series_id and p["period"] in periods]
    selected.sort(key=lambda p: p["period"])
    if len(selected) != len(periods):
        raise ValueError(f"Missing annual-mean observations for {provider} {series_id}")
    return {"operation": "annual_mean", "operands": copy.deepcopy(selected), "mutation": "collection"}


def build_seeds(points: list[dict[str, Any]]) -> list[dict[str, Any]]:
    ix = lookup(points)
    seeds: list[dict[str, Any]] = []
    geo2 = [("DE", "FR"), ("IT", "ES"), ("FR", "NL"), ("DE", "IT"), ("ES", "NL")]
    iso3 = {"DE": "DEU", "FR": "FRA", "IT": "ITA", "ES": "ESP", "NL": "NLD"}
    mutations = ["unit", "unit_multiplier", "price_basis", "adjustment", "concept", "frequency"]

    # 20 difference seeds: 10 Eurostat and 10 World Bank current-price GDP.
    for year in ["2023", "2024"]:
        for j, (ga, gb) in enumerate(geo2):
            seeds.append(pair_seed(
                "difference",
                ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{ga}", year)],
                ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{gb}", year)], mutations[(j + int(year)) % len(mutations)],
            ))
            seeds.append(pair_seed(
                "difference",
                ix[("World Bank", f"NY.GDP.MKTP.CD.{iso3[ga]}", year)],
                ix[("World Bank", f"NY.GDP.MKTP.CD.{iso3[gb]}", year)], mutations[(j + int(year) + 1) % len(mutations)],
            ))

    # 20 ratio seeds: same source families, with constant-price World Bank GDP.
    for year in ["2023", "2024"]:
        for j, (ga, gb) in enumerate(geo2):
            seeds.append(pair_seed(
                "ratio",
                ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{ga}", year)],
                ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{gb}", year)], mutations[(j + 2) % len(mutations)],
            ))
            seeds.append(pair_seed(
                "ratio",
                ix[("World Bank", f"NY.GDP.MKTP.KD.{iso3[ga]}", year)],
                ix[("World Bank", f"NY.GDP.MKTP.KD.{iso3[gb]}", year)], mutations[(j + 3) % len(mutations)],
            ))

    # 20 temporal growth seeds across all four providers.
    for j, geo in enumerate(["DE", "FR", "IT", "ES", "NL"]):
        seeds.append(pair_seed(
            "growth", ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{geo}", "2023")],
            ix[("Eurostat", f"nama_10_gdp.CP_MEUR.B1GQ.{geo}", "2024")], mutations[j % len(mutations)]
        ))
        seeds.append(pair_seed(
            "growth", ix[("World Bank", f"NY.GDP.MKTP.CD.{iso3[geo]}", "2023")],
            ix[("World Bank", f"NY.GDP.MKTP.CD.{iso3[geo]}", "2024")], mutations[(j + 1) % len(mutations)]
        ))
    for provider, sid_pattern in [
        ("ECB", lambda cur: f"EXR.M.{cur}.EUR.SP00.A"),
        ("BIS", lambda cur: f"M.{ {'USD':'US','GBP':'GB','JPY':'JP','CHF':'CH'}[cur] }.{cur}.A"),
    ]:
        for j, cur in enumerate(["USD", "GBP", "JPY", "CHF"]):
            sid = sid_pattern(cur)
            if provider == "BIS":
                area = {"USD": "US", "GBP": "GB", "JPY": "JP", "CHF": "CH"}[cur]
                sid = f"M.{area}.{cur}.A"
            seeds.append(pair_seed(
                "growth", ix[(provider, sid, "2024-01")], ix[(provider, sid, "2024-12")],
                mutations[(j + (0 if provider == "ECB" else 2)) % len(mutations)]
            ))
    # Two additional World Bank constant-price growth tasks reach twenty.
    for j, geo in enumerate(["DE", "FR"]):
        seeds.append(pair_seed(
            "growth", ix[("World Bank", f"NY.GDP.MKTP.KD.{iso3[geo]}", "2023")],
            ix[("World Bank", f"NY.GDP.MKTP.KD.{iso3[geo]}", "2024")], mutations[(j + 4) % len(mutations)]
        ))

    # 20 annual-means of monthly average exchange rates: full year, H1, or H2.
    windows = [
        [f"2024-{m:02d}" for m in range(1, 13)],
        [f"2024-{m:02d}" for m in range(1, 7)],
        [f"2024-{m:02d}" for m in range(7, 13)],
    ]
    specs: list[tuple[str, str, list[str]]] = []
    for provider in ["ECB", "BIS"]:
        for cur in ["USD", "GBP", "JPY", "CHF"]:
            sid = f"EXR.M.{cur}.EUR.SP00.A" if provider == "ECB" else f"M.{ {'USD':'US','GBP':'GB','JPY':'JP','CHF':'CH'}[cur] }.{cur}.A"
            if provider == "BIS":
                area = {"USD": "US", "GBP": "GB", "JPY": "JP", "CHF": "CH"}[cur]
                sid = f"M.{area}.{cur}.A"
            specs.append((provider, sid, windows[0]))
            specs.append((provider, sid, windows[1]))
    for provider, cur in [("ECB", "USD"), ("ECB", "GBP"), ("BIS", "USD"), ("BIS", "GBP")]:
        sid = f"EXR.M.{cur}.EUR.SP00.A" if provider == "ECB" else f"M.{'US' if cur == 'USD' else 'GB'}.{cur}.A"
        specs.append((provider, sid, windows[2]))
    seeds.extend(annual_seed(points, *spec) for spec in specs)

    counts = Counter(seed["operation"] for seed in seeds)
    if len(seeds) != 80 or any(counts[op] != 20 for op in ["difference", "ratio", "growth", "annual_mean"]):
        raise RuntimeError(f"Expected 80 balanced seeds; built {len(seeds)}: {counts}")
    return seeds


def changed_value(field: str, original: str) -> str:
    choices = {
        "unit": "COUNTERFACTUAL_UNIT", "unit_multiplier": "3", "price_basis": "counterfactual chained prices",
        "adjustment": "COUNTERFACTUAL_ADJUSTMENT", "concept": "counterfactual concept",
        "frequency": "Q" if original != "Q" else "M", "collection": "E",
    }
    candidate = choices[field]
    return candidate if candidate != original else f"{candidate}_ALT"


def payload_hash(operation: str, operands: list[dict[str, Any]]) -> str:
    payload = {"operation": operation, "values": [[o["period"], o["value"]] for o in operands]}
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


def metadata_hash(operands: list[dict[str, Any]]) -> str:
    return hashlib.sha256(json.dumps([o["metadata"] for o in operands], sort_keys=True).encode()).hexdigest()


def task_result(operation: str, operands: list[dict[str, Any]]) -> float:
    values = [float(o["value"]) for o in operands]
    if operation == "difference":
        return values[0] - values[1]
    if operation == "ratio":
        return values[0] / values[1]
    if operation == "growth":
        return (values[1] / values[0] - 1.0) * 100.0
    if operation == "annual_mean":
        return sum(values) / len(values)
    raise ValueError(operation)


def make_counterfactual_tasks(seeds: list[dict[str, Any]], rng_seed: int = 20260901) -> list[dict[str, Any]]:
    tasks = []
    opaque = 1000
    for i, seed in enumerate(seeds, 1):
        variants = []
        base = copy.deepcopy(seed["operands"])
        variants.append(("valid", "ACCEPT", base, "none"))

        conflict = copy.deepcopy(base)
        target = 0 if seed["operation"] == "annual_mean" else 1
        field = seed["mutation"]
        for operand in conflict if seed["operation"] == "annual_mean" else [conflict[target]]:
            operand["metadata"][field] = changed_value(field, str(operand["metadata"][field]))
        variants.append(("semantic_conflict", "REJECT", conflict, field))

        missing = copy.deepcopy(base)
        for operand in missing if seed["operation"] == "annual_mean" else [missing[target]]:
            operand["metadata"][field] = None
        variants.append(("missing_obligation", "ABSTAIN", missing, field))

        irrelevant = copy.deepcopy(base)
        for operand in irrelevant:
            operand["metadata"]["release_note"] = "counterfactual-neutral annotation"
        variants.append(("irrelevant_metadata", "ACCEPT", irrelevant, "none"))

        for variant, label, operands, decisive in variants:
            opaque += 1
            tasks.append({
                "task_id": f"Q{opaque:04d}", "set_id": f"S{i:03d}", "variant": variant,
                "operation": seed["operation"], "instruction": {
                    "difference": "report A minus B", "ratio": "report A divided by B",
                    "growth": "report percent change from A to B",
                    "annual_mean": "report the arithmetic mean of the declared monthly-average rate observations",
                }[seed["operation"]],
                "operands": operands, "gold_label": label, "decisive_field": decisive,
                "numeric_result_if_released": task_result(seed["operation"], operands),
                "payload_hash": payload_hash(seed["operation"], operands),
                "metadata_hash": metadata_hash(operands),
            })
    random.Random(rng_seed).shuffle(tasks)
    return tasks


def gate(task: dict[str, Any]) -> tuple[str, str]:
    operation = task["operation"]
    operands = task["operands"]
    if operation == "annual_mean":
        for field in ["unit", "unit_multiplier", "frequency", "collection", "quantity_kind"]:
            vals = [o["metadata"].get(field) for o in operands]
            if any(v is None or v == "" for v in vals):
                return "ABSTAIN", field
            if len(set(vals)) != 1:
                return "REJECT", field
        m = operands[0]["metadata"]
        if m["frequency"] != "M":
            return "REJECT", "frequency"
        if m["collection"] != "A":
            return "REJECT", "collection"
        if m["quantity_kind"] != "rate":
            return "REJECT", "quantity_kind"
        return "ACCEPT", "none"

    a, b = operands
    for field in REQUIRED_PAIR:
        av, bv = a["metadata"].get(field), b["metadata"].get(field)
        if av is None or bv is None or av == "" or bv == "":
            return "ABSTAIN", field
        if av != bv:
            return "REJECT", field
    if operation in {"difference", "ratio"} and a["period"] != b["period"]:
        return "REJECT", "period"
    if operation == "growth":
        if a["series_id"] != b["series_id"] or a["period"] == b["period"]:
            return "REJECT", "series_or_period"
        if float(a["value"]) == 0:
            return "ABSTAIN", "zero_denominator"
    if operation == "ratio" and float(b["value"]) == 0:
        return "ABSTAIN", "zero_denominator"
    return "ACCEPT", "none"


def make_repairs(seeds: list[dict[str, Any]]) -> list[dict[str, Any]]:
    repairs = []
    pair_seeds = [s for s in seeds if s["operation"] in {"difference", "ratio"}][:40]
    for i, seed in enumerate(pair_seeds, 1):
        operands = copy.deepcopy(seed["operands"])
        original = float(operands[1]["value"])
        operands[1]["value"] = original / 1000.0
        operands[1]["metadata"]["unit_multiplier"] = "3"
        repairs.append({
            "task_id": f"R{i:03d}", "operation": seed["operation"], "operands": operands,
            "gold_label": "REPAIR", "repair": "multiply operand B by 10^3 and set multiplier to 0",
            "canonical_b": original, "expected_result": task_result(seed["operation"], seed["operands"]),
        })
    return repairs


def repair_gate(task: dict[str, Any]) -> tuple[str, float | None]:
    a, b = copy.deepcopy(task["operands"])
    diffs = [f for f in REQUIRED_PAIR if a["metadata"].get(f) != b["metadata"].get(f)]
    if diffs != ["unit_multiplier"] or a["metadata"].get("unit") != b["metadata"].get("unit"):
        return "REJECT", None
    try:
        scale = 10 ** (int(b["metadata"]["unit_multiplier"]) - int(a["metadata"]["unit_multiplier"]))
    except (TypeError, ValueError):
        return "ABSTAIN", None
    b["value"] = float(b["value"]) * scale
    b["metadata"]["unit_multiplier"] = a["metadata"]["unit_multiplier"]
    repaired = {**task, "operands": [a, b]}
    decision, _ = gate(repaired)
    return ("REPAIR", task_result(task["operation"], [a, b])) if decision == "ACCEPT" else (decision, None)


def write_agent_prompts(tasks: list[dict[str, Any]], outdir: Path) -> list[str]:
    # Forty complete sets preserve balanced labels and all four operations.
    chosen_sets = sorted({t["set_id"] for t in tasks})[::2]
    evaluation = [t for t in tasks if t["set_id"] in set(chosen_sets)]
    random.Random(260901).shuffle(evaluation)
    conditions = {}
    for condition in ["payload_only", "metadata", "contract"]:
        items = []
        for t in evaluation:
            item = {"task_id": t["task_id"], "operation": t["operation"], "instruction": t["instruction"],
                    "operands": [{"title": o["title"], "period": o["period"], "value": o["value"]} for o in t["operands"]]}
            if condition != "payload_only":
                for dest, src in zip(item["operands"], t["operands"]):
                    dest["metadata"] = src["metadata"]
            items.append(item)
        lead = (
            "You are a statistical data agent. For each task output exactly one JSON object per line with "
            "task_id, decision (ACCEPT, REJECT, or ABSTAIN), and decisive_field. ACCEPT only if the requested "
            "statistical claim is measurement-admissible; REJECT a known conflict; ABSTAIN when load-bearing "
            "metadata is missing. Do not use tools and do not add prose.\n"
        )
        if condition == "contract":
            lead += (
                "Operation contract: difference/ratio require equal concept, unit, unit multiplier, frequency, "
                "adjustment, price basis, collection, and quantity kind, with a common period. Growth requires "
                "those semantic coordinates to match for the same series at different periods and a nonzero base. "
                "Annual_mean requires monthly observations declared as average collection and quantity kind rate. "
                "Ignore release_note. Missing required coordinates must ABSTAIN.\n"
            )
        conditions[condition] = lead + json.dumps(items, ensure_ascii=True)
        (outdir / f"agent_prompt_{condition}.txt").write_text(conditions[condition], encoding="utf-8")
        # Split on complete counterfactual sets so responses cannot be silently
        # truncated by a model's output-token ceiling.
        set_batches = [set(chosen_sets[start:start + 10]) for start in range(0, 40, 10)]
        for batch, batch_sets in enumerate(set_batches, 1):
            batch_items = [item for item, task in zip(items, evaluation) if task["set_id"] in batch_sets]
            (outdir / f"agent_prompt_{condition}_b{batch}.txt").write_text(
                lead + json.dumps(batch_items, ensure_ascii=True), encoding="utf-8"
            )
        # The final ten sets contain the longest annual-series payloads.  Two
        # supplemental half-batches provide a complete retry path if a model
        # hits its output ceiling; scorers let these files override batch 4.
        for suffix, batch_sets in zip(["4a", "4b"], [set(chosen_sets[30:35]), set(chosen_sets[35:40])]):
            batch_items = [item for item, task in zip(items, evaluation) if task["set_id"] in batch_sets]
            (outdir / f"agent_prompt_{condition}_b{suffix}.txt").write_text(
                lead + json.dumps(batch_items, ensure_ascii=True), encoding="utf-8"
            )
    (outdir / "agent_eval_gold.jsonl").write_text(
        "".join(json.dumps({k: t[k] for k in ["task_id", "set_id", "variant", "operation", "gold_label", "decisive_field"]}) + "\n" for t in evaluation),
        encoding="utf-8",
    )
    return chosen_sets


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", type=Path, required=True)
    parser.add_argument("--natural-benchmark", type=Path)
    args = parser.parse_args()
    args.outdir.mkdir(parents=True, exist_ok=True)
    raw = args.outdir / "raw"

    source_points = eurostat_points(raw) + ecb_points(raw) + bis_points(raw) + world_bank_points(raw)
    points = [normalize_point(p) for p in source_points]
    seeds = build_seeds(points)
    tasks = make_counterfactual_tasks(seeds)
    repairs = make_repairs(seeds)

    gate_rows = []
    for task in tasks:
        decision, field = gate(task)
        gate_rows.append({"task_id": task["task_id"], "gold": task["gold_label"], "decision": decision,
                          "expected_field": task["decisive_field"], "observed_field": field,
                          "correct": decision == task["gold_label"]})
    if not all(row["correct"] for row in gate_rows):
        raise RuntimeError(f"Gate failed constructed cases: {[r for r in gate_rows if not r['correct']][:5]}")
    repair_rows = []
    for task in repairs:
        decision, result = repair_gate(task)
        preserved = result is not None and math.isclose(result, task["expected_result"], rel_tol=1e-12, abs_tol=1e-12)
        repair_rows.append({"task_id": task["task_id"], "decision": decision, "result": result,
                            "expected_result": task["expected_result"], "semantics_preserved": preserved})
    if not all(r["decision"] == "REPAIR" and r["semantics_preserved"] for r in repair_rows):
        raise RuntimeError("Repair preservation check failed")

    by_set: dict[str, list[dict[str, Any]]] = {}
    for task in tasks:
        by_set.setdefault(task["set_id"], []).append(task)
    twin_checks = []
    for set_id, members in by_set.items():
        twin_checks.append({
            "set_id": set_id, "one_payload_hash": len({m["payload_hash"] for m in members}) == 1,
            "four_metadata_hashes": len({m["metadata_hash"] for m in members}) == 4,
            "labels": sorted(m["gold_label"] for m in members),
        })
    if not all(x["one_payload_hash"] and x["four_metadata_hashes"] for x in twin_checks):
        raise RuntimeError("Counterfactual invariance check failed")

    with (args.outdir / "tas_semantic_benchmark.jsonl").open("w", encoding="utf-8") as stream:
        for task in tasks:
            stream.write(json.dumps(task, ensure_ascii=True) + "\n")
    with (args.outdir / "tas_repair_benchmark.jsonl").open("w", encoding="utf-8") as stream:
        for task in repairs:
            stream.write(json.dumps(task, ensure_ascii=True) + "\n")
    pd.DataFrame(gate_rows).to_csv(args.outdir / "tas_gate_results.csv", index=False)
    pd.DataFrame(repair_rows).to_csv(args.outdir / "tas_repair_results.csv", index=False)
    chosen_sets = write_agent_prompts(tasks, args.outdir)

    natural = {}
    if args.natural_benchmark and args.natural_benchmark.exists():
        old = [json.loads(line) for line in args.natural_benchmark.read_text(encoding="utf-8").splitlines() if line]
        natural = {
            "n": len(old), "providers": dict(Counter(t["provider"] for t in old)),
            "gold": dict(Counter(t["gold_label"] for t in old)),
            "structurally_executable": sum(bool(t.get("vtl_type_valid")) for t in old),
            "numeric_execution_match": sum(bool(t.get("vtl_numeric_match")) for t in old),
        }

    set_providers = []
    for seed in seeds:
        set_providers.append(seed["operands"][0]["provider"])
    summary = {
        "generated_utc": datetime.now(timezone.utc).isoformat(),
        "controlled_tier": {
            "sets": len(seeds), "tasks": len(tasks),
            "operations": dict(Counter(t["operation"] for t in tasks)),
            "providers_by_set": dict(Counter(set_providers)),
            "labels": dict(Counter(t["gold_label"] for t in tasks)),
            "variants": dict(Counter(t["variant"] for t in tasks)),
            "payload_identical_sets": sum(x["one_payload_hash"] for x in twin_checks),
            "metadata_distinct_sets": sum(x["four_metadata_hashes"] for x in twin_checks),
        },
        "deterministic_gate": {"n": len(gate_rows), "exact_accuracy": sum(r["correct"] for r in gate_rows) / len(gate_rows)},
        "repair_suite": {"n": len(repairs), "repair_success": sum(r["decision"] == "REPAIR" for r in repair_rows) / len(repairs),
                         "semantic_preservation": sum(r["semantics_preserved"] for r in repair_rows) / len(repairs)},
        "model_evaluation_split": {"sets": len(chosen_sets), "tasks": len(chosen_sets) * 4, "selection": "every second set before seeded shuffle"},
        "natural_tier": natural,
        "payload_only_lower_bound": {
            "theorem": "Any deterministic payload-only rule makes one decision for all four members; at least two of four labels are wrong.",
            "maximum_exact_accuracy_per_balanced_set": 0.5,
            "if_always_accept": {"unsafe_release_rate_on_reject": 1.0, "false_refusal_rate_on_valid": 0.0},
        },
        "source_urls": sorted({p["source_url"] for p in points}),
        "interpretation_boundary": "Gold labels are operation-relative obligations declared in the benchmark. Controlled mutations test sensitivity, not the universal invalidity of all calculations on differently described data.",
    }
    (args.outdir / "tas_semantic_summary.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Standards crosswalk, naturalistic-subset audit, and rule sensitivity.

This file deliberately does not import or read the SCAR contract.  It provides
a separately structured implementation based on an explicit codebook below,
then quantifies where the benchmark is grounded in provider-observed field
values and where it uses controlled, schema-valid counterfactual values.

The exercise is not labeled as independent human validation.  It tests
external standards alignment, source provenance, implementation agreement,
and sensitivity to alternative rule choices without pretending that those
checks establish universal statistical truth.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

import pandas as pd

from tas_benchmark import bis_points, ecb_points, eurostat_points
from tas_semantic_counterfactual import world_bank_points


PAIR_COORDINATES = (
    "concept", "unit", "unit_multiplier", "frequency", "adjustment",
    "price_basis", "collection", "quantity_kind",
)
ANNUAL_COORDINATES = ("unit", "unit_multiplier", "frequency", "collection", "quantity_kind")

STANDARDS_CROSSWALK = [
    {
        "source": "SDMX Information Model",
        "url": "https://sdmx.org/wp-content/uploads/SDMX_3-0-0_SECTION_2_FINAL-1_0.pdf",
        "supports": ["concept", "unit", "frequency", "adjustment", "collection"],
        "bounded_interpretation": (
            "SDMX represents observations through structured concepts, dimensions, and attributes. "
            "This supports treating measurement metadata as executable state; it does not itself "
            "select the paper's exact release rule."
        ),
    },
    {
        "source": "SDMX Validation and Transformation Language 2.1",
        "url": "https://sdmx.org/wp-content/uploads/VTL-2.1-Reference-Manual.pdf",
        "supports": ["operation", "dataset compatibility", "explicit validation"],
        "bounded_interpretation": (
            "VTL supplies typed transformation and validation semantics. The paper uses the same "
            "design principle of declared operators and obligations but does not claim VTL conformance."
        ),
    },
    {
        "source": "European Central Bank frequency aggregation guidance",
        "url": "https://data.ecb.europa.eu/help/frequency-aggregation",
        "supports": ["frequency", "collection", "quantity_kind"],
        "bounded_interpretation": (
            "ECB guidance distinguishes averaging indices, summing flows, and end-of-period stocks. "
            "This independently motivates collection and quantity kind as load-bearing coordinates."
        ),
    },
    {
        "source": "Bank for International Settlements SDMX API documentation",
        "url": "https://stats.bis.org/api-doc/v2/",
        "supports": ["series identity", "frequency", "unit", "collection"],
        "bounded_interpretation": (
            "The BIS exposes observations with structured series keys and attributes, supporting the "
            "provenance representation used here without validating every normalization choice."
        ),
    },
]


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def independent_codebook_oracle(task: dict[str, Any]) -> tuple[str, str]:
    """Separately structured codebook implementation, with no contract-file access."""
    operation = task["operation"]
    operands = task["operands"]
    coordinates = ANNUAL_COORDINATES if operation == "annual_mean" else PAIR_COORDINATES
    for coordinate in coordinates:
        values = [operand["metadata"].get(coordinate) for operand in operands]
        if any(value is None or value == "" for value in values):
            return "ABSTAIN", coordinate
        if len({str(value) for value in values}) != 1:
            return "REJECT", coordinate
    if operation == "annual_mean":
        required = {"frequency": "M", "collection": "A", "quantity_kind": "rate"}
        for coordinate, expected in required.items():
            if str(operands[0]["metadata"].get(coordinate)) != expected:
                return "REJECT", coordinate
    elif operation in {"difference", "ratio"}:
        if operands[0]["period"] != operands[1]["period"]:
            return "REJECT", "period"
    elif operation == "growth":
        if operands[0]["series_id"] != operands[1]["series_id"]:
            return "REJECT", "series_id"
        if operands[0]["period"] == operands[1]["period"]:
            return "REJECT", "period"
    denominator_index = 1 if operation == "ratio" else 0 if operation == "growth" else None
    if denominator_index is not None and float(operands[denominator_index]["value"]) == 0:
        return "ABSTAIN", "zero_denominator"
    return "ACCEPT", "none"


def relaxed_oracle(task: dict[str, Any], omitted: str | None = None, missing_as_reject: bool = False) -> tuple[str, str]:
    operation = task["operation"]
    operands = task["operands"]
    coordinates = ANNUAL_COORDINATES if operation == "annual_mean" else PAIR_COORDINATES
    for coordinate in coordinates:
        if coordinate == omitted:
            continue
        values = [operand["metadata"].get(coordinate) for operand in operands]
        if any(value is None or value == "" for value in values):
            return ("REJECT" if missing_as_reject else "ABSTAIN"), coordinate
        if len({str(value) for value in values}) != 1:
            return "REJECT", coordinate
    if operation == "annual_mean":
        for coordinate, expected in {"frequency": "M", "collection": "A", "quantity_kind": "rate"}.items():
            if coordinate != omitted and str(operands[0]["metadata"].get(coordinate)) != expected:
                return "REJECT", coordinate
    if operation in {"difference", "ratio"} and omitted != "period" and operands[0]["period"] != operands[1]["period"]:
        return "REJECT", "period"
    if operation == "growth":
        if omitted != "series_id" and operands[0]["series_id"] != operands[1]["series_id"]:
            return "REJECT", "series_id"
        if omitted != "period" and operands[0]["period"] == operands[1]["period"]:
            return "REJECT", "period"
    denominator_index = 1 if operation == "ratio" else 0 if operation == "growth" else None
    if denominator_index is not None and omitted != "zero_denominator" and float(operands[denominator_index]["value"]) == 0:
        return ("REJECT" if missing_as_reject else "ABSTAIN"), "zero_denominator"
    return "ACCEPT", "none"


def naturalistic_sets(tasks: list[dict[str, Any]]) -> tuple[pd.DataFrame, set[str]]:
    by_set: dict[str, dict[str, dict[str, Any]]] = defaultdict(dict)
    observed: dict[str, set[str]] = defaultdict(set)
    for task in tasks:
        by_set[task["set_id"]][task["variant"]] = task
    for variants in by_set.values():
        for operand in variants["valid"]["operands"]:
            for coordinate, value in operand["metadata"].items():
                if value not in (None, ""):
                    observed[coordinate].add(str(value))
    rows = []
    natural: set[str] = set()
    for set_id, variants in sorted(by_set.items()):
        valid, conflict = variants["valid"], variants["plausible_conflict"]
        coordinate = conflict["mutation_family"]
        changed = [
            str(after["metadata"].get(coordinate))
            for before, after in zip(valid["operands"], conflict["operands"])
            if before["metadata"].get(coordinate) != after["metadata"].get(coordinate)
        ]
        all_observed = bool(changed) and all(value in observed[coordinate] for value in changed)
        if all_observed:
            natural.add(set_id)
        rows.append({
            "set_id": set_id,
            "split": valid["split"],
            "operation": valid["operation"],
            "mutation_family": coordinate,
            "mutated_values": "|".join(changed),
            "mutated_value_observed_elsewhere": all_observed,
            "schema_valid_non_sentinel": bool(changed) and all(
                "COUNTERFACTUAL" not in value.upper() and value.strip() != "" for value in changed
            ),
        })
    return pd.DataFrame(rows), natural


def subset_model_results(cases: pd.DataFrame, natural: set[str]) -> pd.DataFrame:
    subset = cases[cases.set_id.isin(natural)].copy()
    rows = []
    for (condition, model), group in subset.groupby(["condition", "model"]):
        conflicts = group[group.variant.eq("plausible_conflict")]
        rows.append({
            "condition": condition,
            "model": model,
            "sets": group.set_id.nunique(),
            "tasks": len(group),
            "exact_accuracy": float(group.exact.mean()),
            "complete_set_accuracy": float(group.groupby("set_id").exact.all().mean()),
            "unsafe_conflict_accept_rate": float(conflicts.unsafe_conflict_accept.mean()),
        })
    result = pd.DataFrame(rows)
    means = result.groupby("condition").agg(
        models=("model", "size"),
        sets=("sets", "max"),
        tasks=("tasks", "sum"),
        exact_accuracy=("exact_accuracy", "mean"),
        complete_set_accuracy=("complete_set_accuracy", "mean"),
        unsafe_conflict_accept_rate=("unsafe_conflict_accept_rate", "mean"),
    ).reset_index()
    means["model"] = "cross-model mean"
    return pd.concat([result, means[result.columns]], ignore_index=True)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--benchmark", type=Path, required=True)
    parser.add_argument("--model-cases", type=Path, required=True)
    parser.add_argument("--raw-dir", type=Path, required=True)
    parser.add_argument("--outdir", type=Path, required=True)
    args = parser.parse_args()
    args.outdir.mkdir(parents=True, exist_ok=True)
    tasks = load_jsonl(args.benchmark)
    if len(tasks) != 320:
        raise RuntimeError(f"Expected 320 tasks, found {len(tasks)}")

    oracle_rows = []
    for task in tasks:
        decision, field = independent_codebook_oracle(task)
        oracle_rows.append({
            "task_id": task["task_id"], "set_id": task["set_id"], "split": task["split"],
            "variant": task["variant"], "operation": task["operation"],
            "stored_label": task["gold_label"], "stored_field": task["decisive_field"],
            "independent_codebook_label": decision, "independent_codebook_field": field,
            "label_agreement": decision == task["gold_label"],
            "field_agreement": field == task["decisive_field"],
        })
    oracle = pd.DataFrame(oracle_rows)
    oracle.to_csv(args.outdir / "tas_standards_codebook_agreement_v6.csv", index=False)
    if not oracle[["label_agreement", "field_agreement"]].all().all():
        raise RuntimeError("Independent codebook implementation disagrees with stored benchmark")

    natural_frame, natural = naturalistic_sets(tasks)
    natural_frame.to_csv(args.outdir / "tas_mutation_naturalism_v6.csv", index=False)
    cases = pd.read_csv(args.model_cases)
    evaluation_natural = set(natural_frame[
        natural_frame.split.eq("evaluation") & natural_frame.mutated_value_observed_elsewhere
    ].set_id)
    natural_results = subset_model_results(cases, evaluation_natural)
    natural_results.to_csv(args.outdir / "tas_observed_value_subset_results_v6.csv", index=False)

    coordinate_classes = list(PAIR_COORDINATES) + ["period", "series_id", "zero_denominator"]
    sensitivity_rows = []
    for coordinate in coordinate_classes:
        changed = 0
        release_changed = 0
        affected_families: Counter[str] = Counter()
        for task in tasks:
            strict, _ = independent_codebook_oracle(task)
            relaxed, _ = relaxed_oracle(task, omitted=coordinate)
            if relaxed != strict:
                changed += 1
                affected_families[task["variant"]] += 1
            if (relaxed == "ACCEPT") != (strict == "ACCEPT"):
                release_changed += 1
        sensitivity_rows.append({
            "omitted_coordinate": coordinate,
            "tasks_with_decision_change": changed,
            "tasks_with_release_boundary_change": release_changed,
            "affected_variants": json.dumps(dict(affected_families), sort_keys=True),
        })
    sensitivity = pd.DataFrame(sensitivity_rows)
    sensitivity.to_csv(args.outdir / "tas_drop_coordinate_sensitivity_v6.csv", index=False)

    missing_semantics = []
    for task in tasks:
        strict, _ = independent_codebook_oracle(task)
        alternative, _ = relaxed_oracle(task, missing_as_reject=True)
        missing_semantics.append({
            "task_id": task["task_id"], "strict": strict, "missing_as_reject": alternative,
            "three_way_changed": strict != alternative,
            "binary_release_changed": (strict == "ACCEPT") != (alternative == "ACCEPT"),
        })
    missing_frame = pd.DataFrame(missing_semantics)
    missing_frame.to_csv(args.outdir / "tas_missing_semantics_sensitivity_v6.csv", index=False)

    observations = {}
    source_urls = set()
    provider_counts: Counter[str] = Counter()
    for task in tasks:
        if task["variant"] != "valid":
            continue
        for operand in task["operands"]:
            key = (operand["provider"], operand["series_id"], operand["period"], float(operand["value"]))
            observations[key] = operand
            source_urls.add(operand["source_url"])
            provider_counts[operand["provider"]] += 1
    raw_files = [path for path in args.raw_dir.iterdir() if path.is_file() and not path.name.startswith("._")]
    raw_hashes = {path.name: hashlib.sha256(path.read_bytes()).hexdigest() for path in raw_files}
    source_pool_counts = {
        "Eurostat": len(eurostat_points(args.raw_dir)),
        "ECB": len(ecb_points(args.raw_dir)),
        "BIS": len(bis_points(args.raw_dir)),
        "World Bank": len(world_bank_points(args.raw_dir)),
    }
    source_pool_observations = sum(source_pool_counts.values())
    if source_pool_observations != 315 or len(source_urls) != 15:
        raise RuntimeError(
            f"Source lock mismatch: source_pool={source_pool_observations}, "
            f"task_operands={len(observations)}, URLs={len(source_urls)}"
        )
    if not all(url.startswith("https://") for url in source_urls):
        raise RuntimeError("Non-HTTPS source URL")

    summary = {
        "protocol": "Standards crosswalk, separately structured codebook, source lock, and rule sensitivity",
        "human_validation_performed": False,
        "standards_crosswalk": STANDARDS_CROSSWALK,
        "codebook_tasks": len(oracle),
        "codebook_label_agreement": int(oracle.label_agreement.sum()),
        "codebook_decisive_field_agreement": int(oracle.field_agreement.sum()),
        "source_pool_observations": source_pool_observations,
        "source_pool_counts": source_pool_counts,
        "unique_source_observations_used_in_tasks": len(observations),
        "source_urls": len(source_urls),
        "source_providers": sorted(provider_counts),
        "raw_cache_files": len(raw_files),
        "raw_cache_sha256": raw_hashes,
        "mutation_naturalism": {
            "all_sets_with_provider_observed_mutated_value": int(natural_frame.mutated_value_observed_elsewhere.sum()),
            "all_sets": len(natural_frame),
            "evaluation_sets_with_provider_observed_mutated_value": len(evaluation_natural),
            "evaluation_sets": int(natural_frame.split.eq("evaluation").sum()),
            "all_schema_valid_non_sentinel": bool(natural_frame.schema_valid_non_sentinel.all()),
            "interpretation": (
                "Provider-observed means the changed field value appears in another valid source-backed "
                "record in the locked corpus. Other mutations use closed, schema-valid domain values and "
                "must be described as controlled stress tests, not provider-observed records."
            ),
        },
        "missing_as_reject_three_way_changes": int(missing_frame.three_way_changed.sum()),
        "missing_as_reject_binary_release_changes": int(missing_frame.binary_release_changed.sum()),
        "drop_coordinate_sensitivity": sensitivity.to_dict(orient="records"),
        "claim_boundary": (
            "These checks establish implementation agreement, standards alignment, source provenance, "
            "and sensitivity. They do not substitute for independent expert annotation or deployment validation."
        ),
    }
    (args.outdir / "tas_semantic_validation_summary_v6.json").write_text(
        json.dumps(summary, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

