#!/usr/bin/env python3
"""Check the public TAS research package without provider calls."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def load_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def count_jsonl(path: Path) -> int:
    return sum(1 for line in path.read_text(encoding="utf-8").splitlines() if line.strip())


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def check_manifest(entries: list[dict], label: str) -> int:
    checked = 0
    for entry in entries:
        path = ROOT / entry["path"]
        if not path.is_file():
            raise RuntimeError(f"{label} is missing {entry['path']}")
        if digest(path) != entry["sha256"]:
            raise RuntimeError(f"{label} hash mismatch for {entry['path']}")
        checked += 1
    return checked


def main() -> None:
    contract = load_json(ROOT / "protocols/tas_contract_v3.json")
    if contract.get("contract_id") != "SCAR-1.0":
        raise RuntimeError("Unexpected contract identity")

    benchmark = ROOT / "output/experiments/tas_v3/tas_benchmark_v3.jsonl"
    benchmark_rows = count_jsonl(benchmark)
    if benchmark_rows != 320:
        raise RuntimeError(f"Expected 320 benchmark tasks, found {benchmark_rows}")

    primary_dir = ROOT / "output/experiments/tas_api_v5/api_records"
    stability_dir = ROOT / "output/experiments/tas_v6/stability/api_records"
    static_records = sum(count_jsonl(path) for path in primary_dir.glob("*.jsonl"))
    static_records += sum(count_jsonl(path) for path in stability_dir.glob("*.jsonl"))
    if static_records != 3840:
        raise RuntimeError(f"Expected 3840 static records, found {static_records}")

    available = count_jsonl(
        ROOT / "output/experiments/tas_v6/live_commit_available_locked/tas_live_records_v6.jsonl"
    )
    unavailable = count_jsonl(
        ROOT / "output/experiments/tas_v6/live_commit_unavailable_locked/tas_live_records_v6.jsonl"
    )
    if available != 240 or unavailable != 240:
        raise RuntimeError(
            f"Expected 240 sessions in each channel, found {available} and {unavailable}"
        )

    v5 = load_json(
        ROOT / "output/experiments/tas_api_v5/provenance_manifest_v5.json"
    )
    v5_checked = check_manifest(v5["files"], "v5 manifest")

    v6 = load_json(
        ROOT / "output/experiments/tas_v6/audit/tas_v6_forensic_manifest.json"
    )
    v6_checked = check_manifest(v6["tracked_files"], "v6 manifest")
    static_checked = check_manifest(v6["static_files"], "v6 static manifest")

    print("TAS repository check passed")
    print(f"Contract: {contract['contract_id']}")
    print(f"Benchmark tasks: {benchmark_rows}")
    print(f"Static provider records: {static_records}")
    print(f"Live sessions: {available + unavailable}")
    print(f"Verified manifest entries: {v5_checked + v6_checked + static_checked}")


if __name__ == "__main__":
    main()

