function GlyphPreview({ value, active = false }: { value: number; active?: boolean }) {
  const width = 18 + ((value - 100) / 800) * 13;
  return (
    <svg viewBox="0 0 84 100" aria-label={`Sample at weight ${value}`}>
      <path d="M56 38 C56 23 49 16 37 16 C20 16 12 31 12 54 C12 77 22 87 36 87 C46 87 53 82 57 75 L58 86 L72 86 L72 39 C72 22 61 8 39 8 C22 8 11 15 5 26" fill="none" stroke={active ? "#c51f3a" : "currentColor"} strokeLinecap="round" strokeLinejoin="round" strokeWidth={width} />
    </svg>
  );
}

function evenlySpaced<T>(items: T[], desired = 5): T[] {
  if (items.length <= desired) return items;
  return Array.from({ length: desired }, (_, index) => items[Math.round((index * (items.length - 1)) / (desired - 1))]);
}

function seriesPath(samples: GlyphSample[], key: "area" | "maxCurvature" | "minGap"): string {
  if (samples.length < 2) return "";
  const values = samples.map((sample) => sample.metrics[key]);
  const min = Math.min(...values);
  const max = Math.max(...values);
  return values.map((value, index) => {
    const x = 48 + (652 * index) / (values.length - 1);
    const y = 125 - ((value - min) / Math.max(max - min, 0.000001)) * 88;
    return `${index === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`;
  }).join(" ");
}

function MetricPlot({ samples }: { samples: GlyphSample[] }) {
  const actual = samples.length > 1;
  return (
    <svg viewBox="0 0 720 170" role="img" aria-label="Metric continuity plot">
      <g className="plot-grid">
