function OutlineStage({ samples, active }: { samples: GlyphSample[]; active?: GlyphSample }) {
  if (!active || samples.length === 0) {
    return (
      <svg viewBox="0 0 640 380" role="img" aria-label="Representative overlay of endpoint and interpolated outlines">
        <g className="em-grid"><line x1="60" y1="35" x2="60" y2="338" /><line x1="60" y1="338" x2="585" y2="338" /><line x1="60" y1="83" x2="585" y2="83" /><line x1="60" y1="208" x2="585" y2="208" /></g>
        <path className="master-outline" d="M394 143 C385 91 345 65 285 65 C198 65 146 132 146 220 C146 304 191 339 260 339 C320 339 365 306 389 264 L394 333 L485 333 L485 150 C485 51 419 14 303 14 C219 14 154 46 116 100" />
        <path className="active-outline" d="M385 152 C377 96 344 71 287 71 C207 71 159 134 159 218 C159 295 198 329 260 329 C316 329 354 301 377 261 L383 325 L474 325 L474 157 C474 62 414 26 305 26 C228 26 169 55 133 105" />
        <path className="fault-stroke" d="M365 187 C397 195 404 224 379 249 C355 274 322 269 310 243 C296 213 325 180 365 187 Z" />
        <g className="control-points"><line x1="385" y1="152" x2="377" y2="96" /><circle cx="385" cy="152" r="4" /><circle cx="377" cy="96" r="4" /><line x1="377" y1="96" x2="344" y2="71" /><circle cx="344" cy="71" r="4" /><line x1="383" y1="325" x2="474" y2="325" /><circle cx="383" cy="325" r="4" /><circle cx="474" cy="325" r="4" /></g>
        <g className="fault-marker"><circle cx="382" cy="200" r="12" /><text x="382" y="204">×</text></g>
      </svg>
    );
  }

  const first = samples[0];
  const last = samples[samples.length - 1];
  const minX = Math.min(...samples.map((sample) => sample.bbox.minX));
  const minY = Math.min(...samples.map((sample) => sample.bbox.minY));
  const maxX = Math.max(...samples.map((sample) => sample.bbox.maxX));
  const maxY = Math.max(...samples.map((sample) => sample.bbox.maxY));
  const pad = Math.max(maxX - minX, maxY - minY) * 0.12 || 50;
  const viewBox = `${minX - pad} ${-maxY - pad} ${maxX - minX + pad * 2} ${maxY - minY + pad * 2}`;

  return (
    <svg viewBox={viewBox} role="img" aria-label={`Outline of ${active.glyph} at ${active.axis} ${active.coordinate}`}>
      <g transform="scale(1 -1)">
        <path className="actual-endpoint" d={first.svgPath} /><path className="actual-endpoint" d={last.svgPath} />
        <path className="actual-outline" d={active.svgPath} />
      </g>
    </svg>
  );
}

