import type { Contour, GlyphMetrics, Point } from "./types";

export type OutlineCommand = {
  command: "moveTo" | "lineTo" | "quadraticCurveTo" | "bezierCurveTo" | "closePath";
  args: number[];
};

const EPSILON = 0.0001;

function pointOnQuadratic(start: Point, control: Point, end: Point, t: number): Point {
  const mt = 1 - t;
  return {
    x: mt * mt * start.x + 2 * mt * t * control.x + t * t * end.x,
    y: mt * mt * start.y + 2 * mt * t * control.y + t * t * end.y,
  };
}

function pointOnCubic(start: Point, first: Point, second: Point, end: Point, t: number): Point {
  const mt = 1 - t;
  return {
    x: mt ** 3 * start.x + 3 * mt * mt * t * first.x + 3 * mt * t * t * second.x + t ** 3 * end.x,
    y: mt ** 3 * start.y + 3 * mt * mt * t * first.y + 3 * mt * t * t * second.y + t ** 3 * end.y,
  };
}

export function flattenCommands(commands: OutlineCommand[], curveSteps = 10): Contour[] {
  const contours: Contour[] = [];
  let contour: Contour = [];
  let cursor: Point = { x: 0, y: 0 };

  const finishContour = () => {
    if (contour.length > 2) {
      if (!samePoint(contour[0], contour[contour.length - 1])) contour.push({ ...contour[0] });
      contours.push(contour);
    }
    contour = [];
  };

  for (const item of commands) {
    const [a = 0, b = 0, c = 0, d = 0, e = 0, f = 0] = item.args;
    if (item.command === "moveTo") {
      finishContour();
      cursor = { x: a, y: b };
      contour.push(cursor);
    } else if (item.command === "lineTo") {
      cursor = { x: a, y: b };
      contour.push(cursor);
    } else if (item.command === "quadraticCurveTo") {
      const start = cursor;
      const control = { x: a, y: b };
      const end = { x: c, y: d };
      for (let step = 1; step <= curveSteps; step += 1) contour.push(pointOnQuadratic(start, control, end, step / curveSteps));
      cursor = end;
    } else if (item.command === "bezierCurveTo") {
      const start = cursor;
      const first = { x: a, y: b };
      const second = { x: c, y: d };
      const end = { x: e, y: f };
      for (let step = 1; step <= curveSteps; step += 1) contour.push(pointOnCubic(start, first, second, end, step / curveSteps));
      cursor = end;
    } else if (item.command === "closePath") {
      finishContour();
    }
  }
  finishContour();
  return contours;
}

function samePoint(first: Point, second: Point): boolean {
  return Math.abs(first.x - second.x) < EPSILON && Math.abs(first.y - second.y) < EPSILON;
}

export function contourArea(contour: Contour): number {
  let sum = 0;
  for (let index = 0; index < contour.length - 1; index += 1) {
    sum += contour[index].x * contour[index + 1].y - contour[index + 1].x * contour[index].y;
  }
  return sum / 2;
}

function distance(first: Point, second: Point): number {
  return Math.hypot(first.x - second.x, first.y - second.y);
}

function pointSegmentDistance(point: Point, start: Point, end: Point): number {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  if (Math.abs(dx) < EPSILON && Math.abs(dy) < EPSILON) return distance(point, start);
  const t = Math.max(0, Math.min(1, ((point.x - start.x) * dx + (point.y - start.y) * dy) / (dx * dx + dy * dy)));
  return distance(point, { x: start.x + t * dx, y: start.y + t * dy });
}

function orientation(a: Point, b: Point, c: Point): number {
  return (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y);
}

function properIntersection(a: Point, b: Point, c: Point, d: Point): boolean {
  const o1 = orientation(a, b, c);
  const o2 = orientation(a, b, d);
  const o3 = orientation(c, d, a);
  const o4 = orientation(c, d, b);
  return o1 * o2 < -EPSILON && o3 * o4 < -EPSILON;
}

type Segment = { start: Point; end: Point; contour: number; index: number; last: number };

function collectSegments(contours: Contour[]): Segment[] {
  return contours.flatMap((contour, contourIndex) =>
    contour.slice(0, -1).map((start, index) => ({ start, end: contour[index + 1], contour: contourIndex, index, last: contour.length - 2 })),
  );
}

function adjacent(first: Segment, second: Segment): boolean {
  if (first.contour !== second.contour) return false;
  if (Math.abs(first.index - second.index) <= 1) return true;
  return (first.index === 0 && second.index === first.last) || (second.index === 0 && first.index === second.last);
}

export function intersectionCount(contours: Contour[]): number {
  const segments = collectSegments(contours);
  let total = 0;
  for (let first = 0; first < segments.length; first += 1) {
    for (let second = first + 1; second < segments.length; second += 1) {
      if (!adjacent(segments[first], segments[second]) && properIntersection(segments[first].start, segments[first].end, segments[second].start, segments[second].end)) total += 1;
    }
  }
  return total;
}

export function minimumGap(contours: Contour[]): number {
  const segments = collectSegments(contours);
  let minimum = Number.POSITIVE_INFINITY;
  for (let first = 0; first < segments.length; first += 1) {
    for (let second = first + 1; second < segments.length; second += 1) {
      if (adjacent(segments[first], segments[second])) continue;
      const a = segments[first];
      const b = segments[second];
      if (properIntersection(a.start, a.end, b.start, b.end)) return 0;
      minimum = Math.min(
        minimum,
        pointSegmentDistance(a.start, b.start, b.end),
        pointSegmentDistance(a.end, b.start, b.end),
        pointSegmentDistance(b.start, a.start, a.end),
        pointSegmentDistance(b.end, a.start, a.end),
      );
    }
  }
  return Number.isFinite(minimum) ? minimum : 0;
}

export function maximumCurvature(contours: Contour[]): number {
  let maximum = 0;
  for (const contour of contours) {
    for (let index = 1; index < contour.length - 1; index += 1) {
      const previous = contour[index - 1];
      const point = contour[index];
      const next = contour[index + 1];
      const firstLength = distance(previous, point);
      const secondLength = distance(point, next);
      if (firstLength < EPSILON || secondLength < EPSILON) continue;
      const firstAngle = Math.atan2(point.y - previous.y, point.x - previous.x);
      const secondAngle = Math.atan2(next.y - point.y, next.x - point.x);
      const angle = Math.abs(Math.atan2(Math.sin(secondAngle - firstAngle), Math.cos(secondAngle - firstAngle)));
      maximum = Math.max(maximum, angle / ((firstLength + secondLength) / 2));
    }
  }
  return maximum;
}

export function measureOutline(
  commands: OutlineCommand[],
  advanceWidth: number,
  bbox: { minX: number; maxX: number },
): GlyphMetrics {
  const contours = flattenCommands(commands);
  return {
    area: contours.reduce((sum, contour) => sum + Math.abs(contourArea(contour)), 0),
    maxCurvature: maximumCurvature(contours),
    minGap: minimumGap(contours),
    intersections: intersectionCount(contours),
    advanceWidth,
    leftSideBearing: bbox.minX,
    rightSideBearing: advanceWidth - bbox.maxX,
  };
}

import type { ScanResult } from "./types";

export function reportAsJson(result: ScanResult): string {
  return JSON.stringify(result, null, 2);
}

export function reportAsMarkdown(result: ScanResult): string {
  const lines = [
    "# AxisDoctor report",
    "",
    `Font: **${result.summary.familyName}** (${result.summary.postscriptName})`,
    `Scope: ${result.scope}; ${result.sampleCount} samples per axis; ${result.glyphs.length} glyphs`,
    "",
    "| Glyph | Axis location | Problem | Measured change | Severity |",
    "| --- | --- | --- | --- | --- |",
  ];
  if (result.issues.length === 0) lines.push("| — | — | No threshold crossings | — | — |");
  for (const issue of result.issues) {
    lines.push(`| ${issue.glyph} | ${issue.axis}=${issue.coordinate} | ${issue.kind} | ${issue.change} | ${issue.severity} |`);
  }
  lines.push("", "> Measurements are screening signals. Inspect flagged outlines before changing source masters.");
  return lines.join("\n");
}

export function downloadText(name: string, body: string, type = "text/plain"): void {
  const url = URL.createObjectURL(new Blob([body], { type }));
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  URL.revokeObjectURL(url);
}

