import { useEffect, useRef, useState } from "react";
import type { ScanRequest, ScanResult, WorkerMessage } from "./engine/types";

type Progress = { completed: number; total: number; label: string };
type ScanState = "idle" | "scanning" | "complete" | "error";

export function useFontScan() {
  const workerRef = useRef<Worker | null>(null);
  const activeId = useRef("");
  const [state, setState] = useState<ScanState>("idle");
  const [progress, setProgress] = useState<Progress>({ completed: 0, total: 0, label: "" });
  const [result, setResult] = useState<ScanResult | null>(null);
  const [error, setError] = useState("");

  useEffect(() => () => workerRef.current?.terminate(), []);

  async function run(file: File, options: Pick<ScanRequest, "sampleCount" | "scope" | "glyphs">) {
    workerRef.current?.terminate();
    const worker = new Worker(new URL("./workers/analyze.worker.ts", import.meta.url), { type: "module" });
    workerRef.current = worker;
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    activeId.current = id;
    setState("scanning");
    setError("");
    setResult(null);
    setProgress({ completed: 0, total: 0, label: "Reading font tables" });

    worker.onmessage = (event: MessageEvent<WorkerMessage>) => {
      const message = event.data;
      if (message.id !== activeId.current) return;
      if (message.type === "progress") setProgress(message);
      if (message.type === "result") {
        setResult(message.result);
        setState("complete");
        worker.terminate();
      }
      if (message.type === "error") {
        setError(message.message);
        setState("error");
        worker.terminate();
      }
    };
    worker.onerror = (event) => {
      setError(event.message || "The diagnostic worker stopped unexpectedly.");
      setState("error");
      worker.terminate();
    };

    const buffer = await file.arrayBuffer();
    const request: ScanRequest = { id, fileName: file.name, buffer, ...options };
    worker.postMessage(request, [buffer]);
  }

  return { state, progress, result, error, run };
}

