import { create, type Font, type Glyph, type PathCommand } from "fontkit";
import { detectIssues } from "../engine/detect";
import { measureOutline, type OutlineCommand } from "../engine/geometry";
import type { Axis, GlyphSample, ScanRequest, ScanResult, WorkerMessage } from "../engine/types";

type AxisRecord = Record<string, { name: string; min: number; default: number; max: number }>;
type VariableFont = Font & {
  variationAxes: AxisRecord;
  getVariation: (settings: Record<string, number>) => VariableFont;
};

type GlyphTarget = { label: string; codePoint?: number; id?: number };

function post(message: WorkerMessage): void {
  self.postMessage(message);
}

function axisValues(axis: Axis, count: number): number[] {
  return Array.from({ length: count }, (_, index) => {
    const value = axis.min + ((axis.max - axis.min) * index) / Math.max(1, count - 1);
    return Math.round(value * 1000) / 1000;
  });
}

function selectedGlyphs(font: VariableFont, request: ScanRequest): GlyphTarget[] {
  if (request.scope === "full") {
    return Array.from({ length: font.numGlyphs }, (_, id) => {
      const glyph = font.getGlyph(id);
      return { id, label: glyph.name || `gid${id}` };
    });
  }

  const unique = new Map<number, GlyphTarget>();
  for (const text of request.glyphs) {
    const codePoint = text.codePointAt(0);
    if (codePoint === undefined || !font.hasGlyphForCodePoint(codePoint)) continue;
    const glyph = font.glyphForCodePoint(codePoint);
    if (!unique.has(glyph.id)) unique.set(glyph.id, { codePoint, label: text });
  }
  return [...unique.values()];
}

function getGlyph(font: VariableFont, target: GlyphTarget): Glyph {
  return target.id === undefined ? font.glyphForCodePoint(target.codePoint!) : font.getGlyph(target.id);
}

async function scan(request: ScanRequest): Promise<ScanResult> {
  const font = create(new Uint8Array(request.buffer) as never) as VariableFont;
  const axes: Axis[] = Object.entries(font.variationAxes || {}).map(([tag, value]) => ({ tag, ...value }));
  if (axes.length === 0) throw new Error("No variation axes were found. Open a variable TTF, OTF, WOFF, or WOFF2 file.");

  const glyphs = selectedGlyphs(font, request);
  if (glyphs.length === 0) throw new Error("None of the requested glyphs are present in this font.");

  const total = axes.length * glyphs.length * request.sampleCount;
  let completed = 0;
  const samples: GlyphSample[] = [];

  for (const axis of axes) {
    for (const target of glyphs) {
      for (const coordinate of axisValues(axis, request.sampleCount)) {
        const instance = font.getVariation({ [axis.tag]: coordinate });
        const glyph = getGlyph(instance, target);
        const bbox = glyph.bbox;
        samples.push({
          glyph: target.label,
          glyphName: glyph.name || `gid${glyph.id}`,
          axis: axis.tag,
          coordinate,
          svgPath: glyph.path.toSVG(),
          bbox: { minX: bbox.minX, minY: bbox.minY, maxX: bbox.maxX, maxY: bbox.maxY },
          metrics: measureOutline(glyph.path.commands as PathCommand[] as OutlineCommand[], glyph.advanceWidth, bbox),
        });
        completed += 1;
        if (completed % 4 === 0 || completed === total) {
          post({ type: "progress", id: request.id, completed, total, label: `${target.label} / ${axis.tag}` });
          await new Promise((resolve) => setTimeout(resolve, 0));
        }
      }
    }
  }

  const issues = axes.flatMap((axis) =>
    glyphs.flatMap((glyph) => detectIssues(samples.filter((sample) => sample.axis === axis.tag && sample.glyph === glyph.label))),
  );

  return {
    summary: {
      fileName: request.fileName,
      familyName: font.familyName || "Untitled family",
      postscriptName: font.postscriptName || "Unknown PostScript name",
      unitsPerEm: font.unitsPerEm,
      glyphCount: font.numGlyphs,
      xHeight: font.xHeight,
      ascent: font.ascent,
      descent: font.descent,
      axes,
    },
    sampleCount: request.sampleCount,
    scope: request.scope,
    glyphs: glyphs.map((glyph) => glyph.label),
    samples,
    issues,
  };
}

self.onmessage = async (event: MessageEvent<ScanRequest>) => {
  try {
    const result = await scan(event.data);
    post({ type: "result", id: event.data.id, result });
  } catch (error) {
    post({ type: "error", id: event.data.id, message: error instanceof Error ? error.message : "The font could not be analysed." });
  }
};

"""Sample a variable font along each axis and write a machine-readable report."""

from __future__ import annotations

import argparse
import json
import math
from pathlib import Path
from typing import Any, Iterable

from fontTools.pens.areaPen import AreaPen
from fontTools.pens.boundsPen import BoundsPen
from fontTools.ttLib import TTFont


def _axis_record(axis: Any) -> dict[str, Any]:
    return {
        "tag": axis.axisTag,
        "min": axis.minValue,
        "default": axis.defaultValue,
        "max": axis.maxValue,
    }


def _axis_samples(axis: Any, count: int) -> list[float]:
    step = (axis.maxValue - axis.minValue) / max(1, count - 1)
    return [round(axis.minValue + step * index, 3) for index in range(count)]


def _glyph_names(font: TTFont, text: str) -> list[tuple[str, str]]:
    cmap = font.getBestCmap() or {}
    found: list[tuple[str, str]] = []
    seen: set[str] = set()
    for character in text:
        if character.isspace():
            continue
        name = cmap.get(ord(character))
        if name and name not in seen:
            found.append((character, name))
            seen.add(name)
    return found


def _measure(glyph_set: Any, glyph_name: str) -> dict[str, Any]:
    glyph = glyph_set[glyph_name]
    area_pen = AreaPen(glyph_set)
    bounds_pen = BoundsPen(glyph_set)
    glyph.draw(area_pen)
    glyph.draw(bounds_pen)
    bounds = bounds_pen.bounds or (0, 0, 0, 0)
    width = float(glyph.width)
    return {
        "area": round(abs(float(area_pen.value)), 3),
        "bounds": [round(float(value), 3) for value in bounds],
        "advanceWidth": round(width, 3),
        "leftSideBearing": round(float(bounds[0]), 3),
        "rightSideBearing": round(width - float(bounds[2]), 3),
    }


def _relative_change(value: float, reference: float) -> float:
    return 0 if math.isclose(reference, 0) else (value - reference) / reference


def _area_flags(samples: list[dict[str, Any]]) -> Iterable[dict[str, Any]]:
    if len(samples) < 3:
        return []
    first = samples[0]["metrics"]["area"]
    last = samples[-1]["metrics"]["area"]
    flags = []
    for index, sample in enumerate(samples[1:-1], start=1):
        expected = first + (last - first) * index / (len(samples) - 1)
        change = _relative_change(sample["metrics"]["area"], expected)
        if change < -0.22:
            flags.append(
                {
                    "coordinate": sample["coordinate"],
                    "problem": "area collapse",
                    "change": f"{change * 100:.1f}%",
                }
            )
    return flags


def inspect_font(path: Path, text: str, sample_count: int) -> dict[str, Any]:
    font = TTFont(path, lazy=False)
    if "fvar" not in font:
        raise ValueError("No fvar table found; AxisDoctor expects a variable font.")

    axes = list(font["fvar"].axes)
    glyphs = _glyph_names(font, text)
    if not glyphs:
        raise ValueError("None of the requested glyphs are present in this font.")

    report: dict[str, Any] = {
        "font": {
            "path": path.name,
            "unitsPerEm": font["head"].unitsPerEm,
            "glyphCount": len(font.getGlyphOrder()),
        },
        "axes": [_axis_record(axis) for axis in axes],
        "sampleCount": sample_count,
        "glyphs": [],
        "flags": [],
    }

    for character, glyph_name in glyphs:
        for axis in axes:
            samples = []
            for coordinate in _axis_samples(axis, sample_count):
                glyph_set = font.getGlyphSet(location={axis.axisTag: coordinate})
                samples.append(
                    {
                        "coordinate": coordinate,
                        "metrics": _measure(glyph_set, glyph_name),
                    }
                )
            record = {
                "character": character,
                "glyphName": glyph_name,
                "axis": axis.axisTag,
                "samples": samples,
            }
            report["glyphs"].append(record)
            for flag in _area_flags(samples):
                report["flags"].append(
                    {"glyph": character, "axis": axis.axisTag, **flag}
                )
    font.close()
    return report


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="axisdoctor",
        description="Sample variable-font outlines between axis endpoints.",
    )
    parser.add_argument("font", type=Path, help="variable TTF or OTF")
    parser.add_argument("--glyphs", default="ageSoBR8", help="characters to inspect")
    parser.add_argument("--samples", type=int, choices=(5, 9, 17), default=9)
    parser.add_argument("--output", type=Path, help="write JSON here instead of stdout")
    return parser


def main() -> None:
    arguments = build_parser().parse_args()
    report = inspect_font(arguments.font, arguments.glyphs, arguments.samples)
    payload = json.dumps(report, indent=2, ensure_ascii=False)
    if arguments.output:
        arguments.output.write_text(payload + "\n", encoding="utf-8")
    else:
        print(payload)


if __name__ == "__main__":
    main()

