      <aside className="right-panel panel">
        <div className="panel-heading"><strong>Font metrics:</strong></div>
        <dl className="metric-list">
          <div><dt>Advance</dt><dd>{glyphView?.advanceWidth ?? 684}</dd></div>
          <div><dt>Left bearing</dt><dd>{glyphView?.leftSideBearing ?? 18}</dd></div>
          <div><dt>Right bearing</dt><dd>{glyphView?.rightSideBearing ?? 22}</dd></div>
          <div><dt>Ascender</dt><dd>{loadedFont?.ascender ?? 928}</dd></div>
          <div><dt>Descender</dt><dd>{loadedFont?.descender ?? '−236'}</dd></div>
          <div><dt>x-height</dt><dd>{loadedFont?.xHeight ?? 528}</dd></div>
        </dl>
