        {loadedFont?.axes.length ? <div className="native-axes">
          {loadedFont.axes.map((axis) => <AxisSlider
            key={axis.tag}
            tag={axis.tag}
            label={axis.name}
            value={nativeAxisValues[axis.tag] ?? axis.defaultValue}
            min={axis.min}
            max={axis.max}
            step={(axis.max - axis.min) / 100}
            onChange={(value) => setNativeAxisValues((current) => ({ ...current, [axis.tag]: value }))}
          />)}
          <p className="native-note">Values are reported from <code>fvar</code>. This build does not instance variable outlines.</p>
        </div> : <div className="axis-empty">
          <strong>{loadedFont ? '0 native axes' : 'No font loaded'}</strong>
          <p>{loadedFont ? `${loadedFont.fileName} is a static font.` : 'Axes declared in the fvar table will appear here.'}</p>
        </div>}
        <div className="inspector-note"><strong>Process:</strong><p>TTF → parse → glyph commands → SVG</p></div>
        <div className="export-row">
          <button disabled={!loadedFont} onClick={exportSvg}>Export SVG</button>
          <button disabled={!loadedFont} onClick={exportJson}>Export JSON</button>
        </div>
