  onChange: (value: number) => void;
}

export function AxisSlider({
  label,
  value,
  min = 0,
  max = 100,
  step = 1,
  tag,
  onChange,
}: AxisSliderProps) {
  return (
    <label className="axis-control">
      <span>
        <span>{tag && <code>{tag}</code>}{label}</span>
