function testFontBuffer() {
  const emptyPath = new Path();
  const aPath = new Path();
  aPath.moveTo(50, 0);
  aPath.lineTo(300, 700);
  aPath.lineTo(550, 0);
  aPath.close();

  const font = new Font({
    familyName: 'Geometry Study',
    styleName: 'Regular',
    unitsPerEm: 1000,
    ascender: 800,
    descender: -200,
    glyphs: [
      new Glyph({ name: '.notdef', unicode: 0, advanceWidth: 600, path: emptyPath }),
      new Glyph({ name: 'A', unicode: 65, advanceWidth: 600, path: aPath }),
    ],
  });
  return font.toArrayBuffer();
}

describe('local font parsing', () => {
  it('reads names and metrics without uploading the file', () => {
    const buffer = testFontBuffer();
    const file = { name: 'geometry-study.ttf', size: buffer.byteLength } as File;
    const parsed = parseFontFile(buffer, file);

    expect(parsed.familyName).toBe('Geometry Study');
    expect(parsed.styleName).toBe('Regular');
    expect(parsed.unitsPerEm).toBe(1000);
    expect(parsed.ascender).toBe(800);
    expect(parsed.descender).toBe(-200);
    expect(parsed.font.charToGlyph('A').name).toBe('A');
  });
});

import { parse, type Font } from 'opentype.js';

export interface VariationAxis {
  tag: string;
  name: string;
  min: number;
  defaultValue: number;
  max: number;
}

export interface ParsedFont {
  font: Font;
  fileName: string;
  fileSize: number;
  familyName: string;
  styleName: string;
  unitsPerEm: number;
  ascender: number;
  descender: number;
  xHeight: number | null;
  axes: VariationAxis[];
}

interface FvarAxis {
  tag: string;
  minValue: number;
  defaultValue: number;
  maxValue: number;
  name?: Record<string, string>;
}

interface FontTables {
  fvar?: { axes?: FvarAxis[] };
  os2?: { sxHeight?: number };
}

function englishName(record: Record<string, string> | undefined, fallback: string) {
  return record?.en ?? Object.values(record ?? {})[0] ?? fallback;
}

export function parseFontFile(buffer: ArrayBuffer, file: File): ParsedFont {
  const font = parse(buffer);
  const tables = font.tables as FontTables;
  const axes = (tables.fvar?.axes ?? []).map((axis) => ({
    tag: axis.tag,
    name: englishName(axis.name, axis.tag.toUpperCase()),
    min: axis.minValue,
    defaultValue: axis.defaultValue,
    max: axis.maxValue,
  }));

  return {
    font,
    fileName: file.name,
    fileSize: file.size,
    familyName: englishName(font.names.fontFamily, 'Untitled family'),
    styleName: englishName(font.names.fontSubfamily, 'Regular'),
    unitsPerEm: font.unitsPerEm,
    ascender: font.ascender,
    descender: font.descender,
    xHeight: tables.os2?.sxHeight ?? null,
    axes,
  };
}

export function formatFileSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

