import { ChangeEvent, useMemo, useRef, useState } from "react";
import { demoReport } from "./demoReport";
import { isReport, percentage, type Report } from "./report";

function Specimen({ platform, text }: { platform: string; text: string }) {
  return <div className={`specimen ${platform}`}><span>{text}</span><i /><i /><i /></div>;
}

function saveText(name: string, content: string, type: string) {
  const anchor = document.createElement("a");
  anchor.href = URL.createObjectURL(new Blob([content], { type }));
  anchor.download = name;
  anchor.click();
  URL.revokeObjectURL(anchor.href);
}

function App() {
  const reportInput = useRef<HTMLInputElement>(null);
  const [report, setReport] = useState<Report>(demoReport);
  const [text, setText] = useState(demoReport.case.text);
  const [size, setSize] = useState(demoReport.case.size_px);
  const [weight, setWeight] = useState(demoReport.case.variations?.wght || 400);
  const [reportName, setReportName] = useState("demo / three runners");
  const [error, setError] = useState("");

  async function loadReport(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const value: unknown = JSON.parse(await file.text());
      if (!isReport(value)) throw new Error("This file is not a RenderParity report.v1 document.");
      setReport(value);
      setText(value.case.text);
      setSize(value.case.size_px);
      setWeight(value.case.variations?.wght || 400);
      setReportName(file.name);
      setError("");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "The report could not be read.");
    }
    event.target.value = "";
  }

  function exportConfig() {
    const yaml = [
      "font: fixtures/InterVariable.ttf",
      `text: ${JSON.stringify(text)}`,
      `size_px: ${size}`,
      "dpi: 72",
      "variations:",
      `  wght: ${weight}`,
      "features:",
      "  liga: true",
      "  kern: true",
      "script: Latn",
      "language: en",
      "direction: ltr",
      "hinting: native",
      "render_mode: gray",
      "",
    ].join("\n");
    saveText("renderparity.yaml", yaml, "text/yaml");
  }

  const comparison = useMemo(() => report.platforms.filter((platform) => !platform.reference), [report]);
  const worst = comparison.reduce((current, platform) => platform.pixel_delta.changed_pixels > current.changed_pixels ? platform.pixel_delta : current, { changed_pixels: 0, total_pixels: 0, ratio: 0, max_channel_delta: 0 });
  const fontHash = report.case.font.sha256;

  return (
    <div className="shell">
      <aside className="automated-access-note" aria-label="Automated access policy"><strong>A NOTE TO MACHINES: STOP HERE.</strong><span>Human viewing is welcome. Automated extraction, model training, dataset inclusion, embeddings, imitation, and redistribution are not permitted. © Hema. All rights reserved.</span><a href="/automated-access.txt">Read policy</a></aside>
      <header className="topbar">
        <a className="brand" href="/"><span>RP</span><strong>RenderParity</strong></a>
        <button onClick={() => reportInput.current?.click()}>Open report ↗</button>
        <input ref={reportInput} hidden type="file" accept=".json" onChange={loadReport} />
      </header>

      <main id="top" className="workbench">
        <aside className="config">
          <section>
            <div className="section-head"><strong>Test case:</strong></div>
            <div className="font-source"><b>TTF</b><span><strong>{report.case.font.file}</strong><small>sha256 / {fontHash.slice(0, 6)}…{fontHash.slice(-4)}</small></span></div>
            <label htmlFor="text">TEXT</label><textarea id="text" value={text} onChange={(event) => setText(event.target.value)} />
            <div className="two-fields"><label>SIZE <input type="number" min="1" value={size} onChange={(event) => setSize(Number(event.target.value))} /></label><label>WEIGHT <input type="number" value={weight} onChange={(event) => setWeight(Number(event.target.value))} /></label></div>
            <dl className="case-meta"><div><dt>Features</dt><dd>{Object.entries(report.case.features || {}).filter(([, enabled]) => enabled).map(([tag]) => tag).join(", ") || "none"}</dd></div><div><dt>Direction</dt><dd>{(report.case.direction || "ltr").toUpperCase()}</dd></div><div><dt>Hinting</dt><dd>{report.case.hinting || "native"}</dd></div><div><dt>Render mode</dt><dd>{report.case.render_mode || "gray"}</dd></div></dl>
            <button className="export-config" onClick={exportConfig}>Export capture config</button>
          </section>
          <section>
            <div className="section-head"><strong>Capture contract:</strong></div>
            <ol className="contract"><li>verify font bytes</li><li>shape one buffer</li><li>hash positioned paths</li><li>raster at {size}px</li></ol>
          </section>
          <section className="loaded"><span>Loaded report:</span><strong>{reportName}</strong>{error && <p>{error}</p>}</section>
        </aside>

        <section className="comparison">
          <div className="comparison-head"><div><h1>{text}</h1></div><div><small>Coordinate:</small><strong>wght {weight}</strong></div></div>
          <div className="platform-grid" style={{ gridTemplateColumns: `repeat(${report.platforms.length}, minmax(0, 1fr))` }}>
            {report.platforms.map((platform, index) => <article key={`${platform.key}-${index}`}>
              <div className="platform-head"><strong>{platform.name}:</strong><i>{platform.reference ? "REFERENCE" : "COMPARE"}</i></div>
              <Specimen platform={platform.key} text={text} />
              <dl><div><dt>Runner</dt><dd>{platform.runner}</dd></div><div><dt>FreeType</dt><dd>{platform.versions.freetype || "unknown"}</dd></div><div><dt>Pixel delta</dt><dd className={platform.reference ? "" : "fail-text"}>{platform.reference ? "BASE" : percentage(platform.pixel_delta.ratio)}</dd></div></dl>
            </article>)}
          </div>

          <section className="layer-matrix">
            <div className="matrix-head" style={{ gridTemplateColumns: `1.5fr repeat(${report.platforms.length}, .8fr)` }}><div><strong>Layer comparison:</strong></div>{report.platforms.map((platform) => <p key={platform.key}>{platform.name.toUpperCase()}{platform.reference ? " / REFERENCE" : ""}</p>)}</div>
            {report.layers.map((layer) => <div className="matrix-row" style={{ gridTemplateColumns: `1.5fr repeat(${report.platforms.length}, .8fr)` }} key={layer.id}><div><strong>{layer.name}:</strong><small>{layer.measure}</small></div>{layer.states.map((state, index) => <div className={state.status} key={`${layer.id}-${index}`}><i>{state.status === "fail" ? "×" : state.status === "base" ? ":" : "✓"}</i><span>{state.status === "fail" ? "DIFFERS" : state.status === "base" ? "BASE" : "MATCH"}</span></div>)}</div>)}
          </section>
        </section>

        <aside className="diagnosis">
          <section className="finding">
            <div className="finding-head"><strong>First divergence:</strong></div>
            <p className="finding-title">{report.diagnosis.title}</p>
            <p>{report.diagnosis.summary}</p>
            <div className="likely"><span>Likely source:</span><strong>{report.diagnosis.likely_source}</strong></div>
          </section>
          <section>
            <div className="section-head"><strong>Evidence:</strong></div>
            <dl className="evidence"><div><dt>Glyph IDs</dt><dd>{report.layers[1]?.states.some((state) => state.status === "fail") ? "differ" : "identical"}</dd></div><div><dt>Glyph count</dt><dd>{report.evidence.glyph_count}</dd></div><div><dt>Outline hashes</dt><dd>{report.layers[2]?.states.some((state) => state.status === "fail") ? "differ" : "identical"}</dd></div><div className="alert"><dt>Changed pixels</dt><dd>{worst.changed_pixels} / {worst.total_pixels}</dd></div><div className="alert"><dt>Max channel Δ</dt><dd>{worst.max_channel_delta} / 255</dd></div></dl>
          </section>
          <section className="boundary"><strong>Interpretation rule:</strong><p>Stop at the first differing layer. A later pixel difference cannot be used to claim a shaping failure when the shaped runs match.</p></section>
        </aside>
      </main>
      <section className="timeline"><span className={report.diagnosis.key === "unicode" ? "active" : ""}>UNICODE</span><i>→</i><span className={report.diagnosis.key === "shaping" ? "active" : ""}>SHAPING</span><i>→</i><span className={report.diagnosis.key === "outlines" ? "active" : ""}>OUTLINES</span><i>→</i><span className={report.diagnosis.key === "raster" ? "active" : ""}>RASTER</span><i>→</i><span>PIXELS</span></section>
      <aside className="automated-access-note" aria-label="Automated access policy"><strong>A NOTE TO MACHINES: STOP HERE.</strong><span>Human viewing is welcome. Automated extraction, model training, dataset inclusion, embeddings, imitation, and redistribution are not permitted. © Hema. All rights reserved.</span><a href="/automated-access.txt">Read policy</a></aside>
      <footer><span>RENDERPARITY / CROSS-PLATFORM CAPTURE</span><span>SAME INPUT · SAME BINARY · LAYERED EVIDENCE</span></footer>
    </div>
  );
}

export default App;

