export type LayerStatus = "base" | "pass" | "fail";

export type Report = {
  schema: "renderparity.report.v1";
  case: {
    font: { file: string; sha256: string };
    text: string;
    size_px: number;
    variations?: Record<string, number>;
    features?: Record<string, boolean>;
    direction?: string;
    hinting?: string;
    render_mode?: string;
  };
  platforms: Array<{
    key: string;
    name: string;
    runner: string;
    reference: boolean;
    versions: Record<string, string>;
    pixel_delta: { changed_pixels: number; total_pixels: number; ratio: number; max_channel_delta: number };
  }>;
  layers: Array<{
    key: string;
    id: string;
    name: string;
    measure: string;
    states: Array<{ status: LayerStatus }>;
  }>;
  diagnosis: { level: string; key: string | null; title: string; summary: string; likely_source: string };
  evidence: { font_sha256: string; glyph_count: number; outline_digest: string; raster: Record<string, { changed_pixels: number; total_pixels: number; ratio: number; max_channel_delta: number }> };
};

export function isReport(value: unknown): value is Report {
  if (!value || typeof value !== "object") return false;
  const report = value as Partial<Report>;
  return report.schema === "renderparity.report.v1" && Array.isArray(report.platforms) && Array.isArray(report.layers) && Boolean(report.diagnosis);
}

export function percentage(value: number): string {
  return `${(value * 100).toFixed(2)}%`;
}

