import type { ShapedGlyph } from "./engine/types";
import { useShaper } from "./useShaper";

const initialFeatures = { liga: true, kern: true, calt: false, frac: false, ss01: false };
type Feature = keyof typeof initialFeatures;
type DisplayGlyph = ShapedGlyph & { label: string; advance: number; offset: string };

const onRun: DisplayGlyph[] = [
  { gid: 82, cluster: 0, label: "o", name: "o", advance: 500, ax: 500, ay: 0, dx: 0, dy: 0, offset: "0, 0", flags: 0, path: "" },
  { gid: 5044, cluster: 1, label: "ffi", name: "f_f_i", advance: 786, ax: 786, ay: 0, dx: 0, dy: 0, offset: "0, 0", flags: 0, path: "" },
  { gid: 70, cluster: 4, label: "c", name: "c", advance: 468, ax: 468, ay: 0, dx: -7, dy: 0, offset: "−7, 0", flags: 0, path: "" },
  { gid: 72, cluster: 5, label: "e", name: "e", advance: 492, ax: 492, ay: 0, dx: 0, dy: 0, offset: "0, 0", flags: 0, path: "" },
];
const offRun: DisplayGlyph[] = [
  { gid: 82, cluster: 0, label: "o", name: "o", advance: 500, ax: 500, ay: 0, dx: 0, dy: 0, offset: "0, 0", flags: 0, path: "" },
  { gid: 73, cluster: 1, label: "f", name: "f", advance: 325, ax: 325, ay: 0, dx: 0, dy: 0, offset: "0, 0", flags: 0, path: "" },
