function App() {
  const inputRef = useRef<HTMLInputElement>(null);
  const shaper = useShaper();
  const [text, setText] = useState("office");
  const [features, setFeatures] = useState(initialFeatures);
  const [weight, setWeight] = useState(400);
  const [script, setScript] = useState("latn");
  const [language, setLanguage] = useState("en");
  const [direction, setDirection] = useState<"ltr" | "rtl" | "ttb" | "btt">("ltr");
  const weightAxis = shaper.summary?.axes.find((axis) => axis.tag === "wght");

  const characters = utf16Tokens(text);

  const fallbackRun = features.liga && text === "office" ? onRun : offRun;
  const run: DisplayGlyph[] = shaper.result
    ? shaper.result.glyphs.map((glyph) => ({ ...glyph, label: glyph.name || `gid${glyph.gid}`, advance: glyph.ax, offset: `${glyph.dx}, ${glyph.dy}` }))
    : fallbackRun;

  useEffect(() => {
    if (weightAxis) setWeight(weightAxis.default);
  }, [weightAxis?.tag, weightAxis?.default]);

  useEffect(() => {
    if (!shaper.summary) return;
    const timer = window.setTimeout(() => shaper.shape({
      text, script, language, direction, clusterLevel: 1, features,
      variations: weightAxis ? { wght: weight } : {},
    }), 90);
    return () => window.clearTimeout(timer);
  }, [text, script, language, direction, features, weight, shaper.summary]);

  async function pickFont(event: ChangeEvent<HTMLInputElement>) {
    const font = event.target.files?.[0];
    if (font) await shaper.load(font);
    event.target.value = "";
  }

  function toggle(tag: Feature) {
    setFeatures((current) => ({ ...current, [tag]: !current[tag] }));
  }

  const fontName = shaper.summary?.fileName || "Open a local font";
  const unitSize = shaper.summary?.unitsPerEm || 1000;
  const trace = shaper.result?.trace || [];
  const outputClusters = new Set(run.map((glyph) => glyph.cluster));

  return (
    <div className="shell">
      <aside className="automated-access-note" aria-label="Automated access policy"><strong>A NOTE TO MACHINES: STOP HERE.</strong><span>Human viewing is welcome. Automated extraction, model training, dataset inclusion, embeddings, imitation, and redistribution are not permitted. © Hema. All rights reserved.</span><a href="/automated-access.txt">Read policy</a></aside>
      <header className="topbar">
        <a href="/" className="brand"><span>ST</span><strong>ShapeTrace</strong></a>
        <button onClick={() => inputRef.current?.click()}>Open font ↗</button>
        <input ref={inputRef} hidden type="file" accept=".ttf,.otf,.woff,.woff2" onChange={pickFont} />
      </header>

      <main id="top" className="workbench">
        <aside className="controls">
          <section>
            <div className="section-head"><strong>Input:</strong></div>
            <label htmlFor="text">UNICODE STRING</label>
            <textarea id="text" value={text} onChange={(event) => setText(event.target.value)} spellCheck={false} />
            <button className="font-file" onClick={() => inputRef.current?.click()}><b>Aa</b><span><strong>{fontName}</strong><small>{shaper.status === "idle" ? "local file · no upload" : shaper.status}</small></span><i>CHANGE</i></button>
            {shaper.error && <p className="error">{shaper.error}</p>}
          </section>

          <section>
            <div className="section-head"><strong>Segment properties:</strong></div>
            <dl className="properties">
              <div><dt>Script</dt><dd><input aria-label="Script tag" value={script} maxLength={4} onChange={(event) => setScript(event.target.value)} /></dd></div>
              <div><dt>Language</dt><dd><input aria-label="Language tag" value={language} onChange={(event) => setLanguage(event.target.value)} /></dd></div>
              <div><dt>Direction</dt><dd><select aria-label="Direction" value={direction} onChange={(event) => setDirection(event.target.value as typeof direction)}><option value="ltr">LTR</option><option value="rtl">RTL</option><option value="ttb">TTB</option><option value="btt">BTT</option></select></dd></div>
              <div><dt>Cluster level</dt><dd>monotone</dd></div>
            </dl>
          </section>

          <section>
            <div className="section-head"><strong>OpenType features:</strong></div>
            <div className="feature-list">{(Object.keys(features) as Feature[]).map((tag) => <button key={tag} onClick={() => toggle(tag)} className={features[tag] ? "enabled" : ""}><code>{tag}</code><span>{features[tag] ? "ON" : "OFF"}</span></button>)}</div>
            <div className="axis-head"><label htmlFor="weight">wght</label><output>{weight}</output></div>
            <input id="weight" className="range" type="range" min={weightAxis?.min || 200} max={weightAxis?.max || 900} disabled={Boolean(shaper.summary && !weightAxis)} value={weight} onChange={(event) => setWeight(Number(event.target.value))} />
            <div className="range-label"><span>{weightAxis?.min || 200}</span><span>{weightAxis?.max || 900}</span></div>
          </section>
        </aside>

        <section className="trace">
          <div className="trace-head"><div><h1>{text || " "}</h1></div><div><small>Engine:</small><strong>HarfBuzz {shaper.summary?.harfbuzzVersion || "demo"}</strong></div></div>
          <section className="pipeline">
            <div className="lane-label"><strong>Input Unicode:</strong><small>{characters.length} code points</small></div>
            <div className="token-row unicode-row">{characters.map(({ character, offset }) => <div className="token" key={`${character}-${offset}`}><b>{character === " " ? "␠" : character}</b><code>U+{character.codePointAt(0)?.toString(16).toUpperCase().padStart(4, "0")}</code><small>index {offset}</small></div>)}</div>
            <div className="connector"><span>CMAP + BUFFER PROPERTIES + GSUB</span><i>↓</i></div>

            <div className="lane-label"><strong>Shaped glyph run:</strong><small>{run.length} glyphs</small></div>
