import { useEffect, useRef, useState } from "react";
import type { FontSummary, ShapeResult, ShapingInput, WorkerRequest, WorkerResponse } from "./engine/types";

export function useShaper() {
  const worker = useRef<Worker>();
  const latestShape = useRef("");
  const [summary, setSummary] = useState<FontSummary | null>(null);
  const [result, setResult] = useState<ShapeResult | null>(null);
  const [status, setStatus] = useState<"idle" | "loading" | "ready" | "shaping" | "error">("idle");
  const [error, setError] = useState("");

  useEffect(() => {
    const instance = new Worker(new URL("./workers/shape.worker.ts", import.meta.url), { type: "module" });
    worker.current = instance;
    instance.onmessage = (event: MessageEvent<WorkerResponse>) => {
      const message = event.data;
      if (message.type === "loaded") {
        setSummary(message.summary);
        setStatus("ready");
      } else if (message.type === "shaped" && message.id === latestShape.current) {
        setResult(message.result);
        setStatus("ready");
      } else if (message.type === "error") {
        setError(message.message);
        setStatus("error");
      }
    };
    instance.onerror = (event) => { setError(event.message); setStatus("error"); };
    return () => instance.terminate();
  }, []);

  async function load(file: File) {
    setStatus("loading");
    setError("");
    setResult(null);
    const buffer = await file.arrayBuffer();
    const request: WorkerRequest = { type: "load", id: `load-${Date.now()}`, fileName: file.name, buffer };
    worker.current?.postMessage(request, [buffer]);
  }

  function shape(input: ShapingInput) {
    if (!summary) return;
    const id = `shape-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    latestShape.current = id;
    setStatus("shaping");
    const request: WorkerRequest = { type: "shape", id, input };
    worker.current?.postMessage(request);
  }

  return { summary, result, status, error, load, shape };
}

/// <reference lib="webworker" />

import { create, type Font } from "fontkit";
import initializeHarfBuzz from "harfbuzzjs/hb.js";
import wrapHarfBuzz from "harfbuzzjs/hbjs.js";
import { featureString } from "../engine/cluster";
import type { FontSummary, ShapeResult, ShapingInput, TraceEvent, WorkerRequest, WorkerResponse } from "../engine/types";

type FontWithFeatures = Font & { availableFeatures: string[] };

let hb: any;
let blob: any;
let face: any;
let summary: FontSummary | null = null;

function post(response: WorkerResponse): void {
  self.postMessage(response);
}

async function engine(): Promise<any> {
  if (!hb) {
    const module = await initializeHarfBuzz({ locateFile: () => "/hb.wasm" });
    hb = wrapHarfBuzz(module);
  }
  return hb;
}

function destroyFont(): void {
  face?.destroy();
  blob?.destroy();
  face = null;
  blob = null;
}

async function loadFont(fileName: string, buffer: ArrayBuffer): Promise<FontSummary> {
  const harfbuzz = await engine();
  destroyFont();
  blob = harfbuzz.createBlob(buffer);
  face = harfbuzz.createFace(blob, 0);
  if (!face.upem) throw new Error("The file did not expose a usable OpenType face.");

  const parsed = create(new Uint8Array(buffer.slice(0)) as never) as FontWithFeatures;
  const axes = Object.entries(face.getAxisInfos() as Record<string, { min: number; default: number; max: number }>).map(([tag, values]) => ({ tag, ...values }));
  summary = {
    fileName,
    familyName: parsed.familyName || "Untitled family",
    postscriptName: parsed.postscriptName || "Unknown PostScript name",
    unitsPerEm: face.upem,
    glyphCount: parsed.numGlyphs,
    axes,
    availableFeatures: parsed.availableFeatures || [],
    harfbuzzVersion: harfbuzz.version_string(),
  };
  return summary;
}

function usefulTrace(records: any[]): TraceEvent[] {
  let stage: TraceEvent["stage"] = "OTHER";
  const kept: TraceEvent[] = [];
  for (const record of records) {
    const message = String(record.m || "");
    if (message.startsWith("start table GSUB")) stage = "GSUB";
    if (message.startsWith("start table GPOS")) stage = "GPOS";
    const meaningful = /^(start|end) table|^(start|end) lookup|substitute|position|kerning/i.test(message);
    if (!meaningful) continue;
    kept.push({
      stage,
      message,
      glyphs: Array.isArray(record.t) ? record.t.slice(0, 48).map((glyph: any) => ({ g: glyph.g, cl: glyph.cl, ax: glyph.ax, ay: glyph.ay, dx: glyph.dx, dy: glyph.dy })) : [],
    });
    if (kept.length === 160) break;
  }
  return kept;
}

function shapeText(input: ShapingInput): ShapeResult {
  if (!summary || !face) throw new Error("Open a font before shaping text.");
  const font = hb.createFont(face);
  font.setScale(summary.unitsPerEm, summary.unitsPerEm);
  if (Object.keys(input.variations).length) font.setVariations(input.variations);

  const buffer = hb.createBuffer();
  buffer.addText(input.text);
  buffer.guessSegmentProperties();
  if (input.direction) buffer.setDirection(input.direction);
  if (input.script) buffer.setScript(input.script);
  if (input.language) buffer.setLanguage(input.language);
  buffer.setClusterLevel(input.clusterLevel);

  const rawTrace = hb.shapeWithTrace(font, buffer, featureString(input.features), 0, 0);
  const glyphs = buffer.json().map((glyph: any) => ({
    gid: glyph.g,
    name: font.glyphName(glyph.g),
    cluster: glyph.cl,
    ax: glyph.ax,
    ay: glyph.ay,
    dx: glyph.dx,
    dy: glyph.dy,
    flags: glyph.flags,
    path: font.glyphToPath(glyph.g),
  }));
  const result: ShapeResult = {
    input,
    glyphs,
    totalAdvance: glyphs.reduce((total: number, glyph: { ax: number }) => total + glyph.ax, 0),
    trace: usefulTrace(rawTrace),
  };
  buffer.destroy();
  font.destroy();
  return result;
}

self.onmessage = async (event: MessageEvent<WorkerRequest>) => {
  try {
    if (event.data.type === "load") post({ type: "loaded", id: event.data.id, summary: await loadFont(event.data.fileName, event.data.buffer) });
    else post({ type: "shaped", id: event.data.id, result: shapeText(event.data.input) });
  } catch (error) {
    post({ type: "error", id: event.data.id, message: error instanceof Error ? error.message : "HarfBuzz could not shape this input." });
  }
};

