import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

from unit_distance_font.geometry import graph_from_paths, squared_length, validate_graph
from unit_distance_font.glyphs import GLYPHS, GRID_HEIGHT, GRID_WIDTH


class UnitDistanceAlphabetTests(unittest.TestCase):
    def test_contains_complete_latin_uppercase_alphabet(self) -> None:
        self.assertEqual("".join(GLYPHS), "ABCDEFGHIJKLMNOPQRSTUVWXYZ")

    def test_every_edge_is_exactly_one_unit(self) -> None:
        for letter, paths in GLYPHS.items():
            with self.subTest(letter=letter):
                graph = graph_from_paths(paths)
                self.assertTrue(graph.edges)
                self.assertTrue(all(squared_length(edge) == 1 for edge in graph.edges))

    def test_every_glyph_is_connected_and_inside_grid(self) -> None:
        for letter, paths in GLYPHS.items():
            with self.subTest(letter=letter):
                self.assertEqual(validate_graph(graph_from_paths(paths)), [])

    def test_design_grid_is_five_by_seven(self) -> None:
        self.assertEqual((GRID_WIDTH, GRID_HEIGHT), (5, 7))

    def test_alphabet_totals_match_the_published_certificate(self) -> None:
        graphs = [graph_from_paths(paths) for paths in GLYPHS.values()]
        self.assertEqual(sum(len(graph.nodes) for graph in graphs), 467)
        self.assertEqual(sum(len(graph.edges) for graph in graphs), 449)
        self.assertEqual(sum(graph.connected for graph in graphs), 26)


if __name__ == "__main__":
    unittest.main()
